"kapsam": "tam",
"kapsam_notu": "Raporun 8.2 bölümü konuyu rakamla ve gerekçeyle anlatıyor: program büyüklüğü, birim fiyat tahmini, kanal, standart, risk. Web kullanılmadı. Not: 8.2 bölümü görev listesindeki s_cont dosyasında değil, aynı raporun sec_other_niches.js dosyasında. Doğrulama için sec_other_niches.js, sec_cranes_launchers.js, sec_regulatory.js, sec_exec.js ve sec_company.js de okundu; bunlar görev listesinde yoktu ama aynı raporun bölümleri. s_mro dosyasında konuya ait satır yok. Birim fiyat, flat rack sayısı ve bütçe rakamlarının tamamı raporda tahmin işaretli.",
"kanit": 4,
"web": [],
"celiskiler": [
"Kart ve özet kesin 4.000 kanca yükleyici yazıyor; Hiab kaynağı 4.000'e kadar diyor ve 2021 tarihli. Raporun kendi içinde de iki kullanım var: 8.2 metni ve Tablo 8.6.1 4.000 adede kadar, Tablo 8.2.1, Tablo 8.4.2 ve Tablo Ö.1 kesin 4.000. Kaynak: inceleme 5 Ekim 2026, kart01_sadakat; 01 rapor s_other, s_crane, s_cont, s_exec.",
"Kartta rakip analizi yok: flat rack'te mevcut tedarikçiler ve fiyat düzeyi yazmıyor. Rapor 8.2 yalnız birim fiyat tahmini veriyor, rakip adı vermiyor. Kaynak: inceleme zayıf yanlar; 01 rapor s_other 8.2.",
"Kartın 30 günlük ödeme vadesi avantajı NSPA, BM ve AB kamusuna doğrudan satışta geçerli; flat rack'in muhatapları Hiab, Palfinger, Koluman gibi özel OEM'ler ve onlarda vade 50 ile 109 gün. Kart bu çelişkiyi ele almıyor. Kaynak: inceleme zayıf yanlar.",
"Ağaç yeri tartışmalı: inceleme dört savunma kolunun Özel firmalar kolunda durmasını fatura kesilen taraf kuralına bağlıyor; kayıt kapıları ve nihai alıcı kamu. Öneri: şemsiye Savunma kartı Devlet altında, bu kolda kanal özel ana yüklenici etiketi. Kaynak: inceleme ağaç notları.",
"Flat rack sayısı 8.000-16.000 ve birim fiyatlar raporda tahmin işaretli; kart bunları rakam olarak vermiyor. Kaynak: 01 rapor s_other 8.2.",
"Kartın 30 Eylül 2026 son günlü YETEN ve SSB fuar başvurusu geçti; yapıldığı dosyalarda yok. Kaynak: inceleme tutarsızlık ve eskiyenler.",
"Duyarlılık ifadesi iki yerde farklı: Tablo 7.2 notu ilk dört nişin tüm senaryolarda ilk altı içinde kaldığını, Tablo Ö.1 notu ilk beş içinde kaldığını yazıyor. Kaynak: 01 rapor s_score Tablo 7.2; s_exec Tablo Ö.1.",
"Prototip ve test bütçesi konteyner gövdesi ve kalıp setiyle ortak kalem; flat rack'e düşen pay çalışmalarda yok. 20-80 bin avro MIL-STD-810 ve AECTP testleri için; STANAG 2413 testinin bütçesi ayrı verilmemiş. Kaynak: 01 rapor s_road Tablo 9.2."
],
"degisiklikler": [
"puan_metni: Tablo 8.2.1 kalem adları dosyadaki gibi düzeltildi; Tablo 8.6.2 puanı 4 eklendi; teknik uyumun tesis verisiyle güncelleneceği notu eklendi.",
"ne: kanca yükleyici gövdesinin kaynakta olmayan ayrıntılı tanımı çıkarıldı; ISO konteyner ölçüsü ifadesi kaynaktaki hâline yaklaştırıldı; ML6 gri alan eklendi.",
"neden: Eskişehir 10 ton ve 7 metre sınırının flat rack için yeterli olduğu bilgisi eklendi; yüksek adet gerekçesi Tablo 8.6.2'ye bağlandı.",
"rakamlar: PLS satırına 6.300'den fazla konteyner elleçleme ünitesi eklendi; Hiab Defence Logistics Haziran 2026 eklendi; Eskişehir sınırı eklendi; 20-80 bin avronun MIL-STD-810 ve AECTP testleri olduğu açıklandı; prototip kaleminin üç ürünü kapsadığı belirtildi.",
"durum: bandın gerekçesi netleştirildi; rekabet puanı 2 zayıf nokta olarak eklendi.",
"acik_sorular: Hyva ve Marrel eklendi; Hiab Defence Logistics sorusu eklendi; tesis eşiklerinin Tablo 7.4 kaynağı yazıldı.",
"adimlar: BMC portal kaydı çıkarıldı, kaynakta yalnız Koluman portalı var; Üretim müdürü ataması çıkarıldı, rapor kişi atamıyor; kim alanları raporun çekirdek ekip tanımına bağlandı; bir ay içinde ifadesi yaklaşık 22 Ekim 2026 olarak hesaplandı ve hesap olduğu yazıldı; Mart 2027 ve Eylül 2027 tarihlerinin hesap olduğu yazıldı.",
"riskler: 20-80 bin avronun STANAG 2413 testi değil MIL-STD-810 ve AECTP testleri bütçesi olduğu düzeltildi; tedarikçi onayı kayması yorum olarak işaretlendi; Tablo 10.1 olasılık ve etki dereceleri eklendi; robotik kaynak eksikliği riski eklendi; ödeme vadesi ayrı risk yapıldı ve yerli ana yüklenici vade riski eklendi; AB çelik koruma önlemi riski eklendi.",
"kapilar: ilk dilim toplamı 100-250 bin avro yerine hesapla 95-285 bin avro yazıldı; yatirim ve yol için varsayım notu eklendi; desteklerle yarıya inme notu eklendi.",
"takvim: Ekim 2026 kalemi yaklaşık 22 Ekim 2026 olarak netleştirildi ve hesap olduğu yazıldı; Aralık 2026 ve Haziran 2027 AB çelik koruma değerlendirmesi eklendi; IDEF kaleminde SSB başvurusunun geçtiği notu eklendi; Mart 2027 kalemine belgeler ve MSB görüşü eklendi.",
"tam_calisma: Tablo 7.1 başlığı dosyadaki tam hâliyle yazıldı, baz senaryo eki eklendi; Tablo 7.4, Tablo 8.4.2, Tablo 8.6.2 ve Tablo 9.3 eklendi.",
"celiskiler: rapor içindeki 4.000 ve 4.000'e kadar ikiliği eklendi; Tablo 7.2 ile Tablo Ö.1 arasındaki ilk altı ve ilk beş farkı eklendi; bütçe kalemlerinin ortak olduğu ve STANAG testi bütçesinin ayrı olmadığı eklendi.",
"kaynaklar ve kapsam_notu: görev listesinde olmayan ama okunan bölüm dosyaları açıkça işaretlendi."
],
