"riskler": [
"Askerî vinç talebi 10 ile 15 yılda bir filo yenileme dalgası hâlinde gelir. Bundeswehr'de 2024 ile 2026 arası yeni vinç siparişi bulunamadı. Ara dönemde iş yedek parça, ömür uzatma ve ataşmana düşer.",
"Rapor sistematik bir askerî vinç programı bulamamış; pazar Liebherr, Grove ve Tadano'nun elinde. Kaynak 01 özet, Tablo Ö.2.",
"Kalifikasyon 12 ile 24 ay sürer. ASELSAN'ın Nisan 2020 çalışması alt yüklenicilerin ana yükleniciye bağımlılığını ve yatırım geri dönüş sorununu kaydeder. Ödeme vadesi konusunda sayısal kamu verisi yok.",
"Tesis sınırı 10 ton ve 7 metre; bom kutuları dışarıda kalır. Teknik uyum puanı kamuya açık bilgiye dayalı varsayım. Hidrokon'un Roketsan örneği tek taraflı beyan.",
"Puan 3,35 raporun ikincil eşiği 3,40'ın altında; rapor nişi koşullu sayar."
],
