"riskler": [
"AS9100 geniş yorumlanırsa havacılık sertifikasyon yükü nişi 2/5'e düşürür; lazer ve CNC odaklı akış zaten bu puanı vermiş.",
"Tersaneler kendi blok atölyelerine sahip; Ankara'dan yüz tonluk blok taşımak maliyetli ve gabariyle sınırlı. Deniz kaynağı klas kuruluşu onayı ister.",
"Uçağa özel krikolar, motor sehpaları ve mühimmat arabaları ihracat kontrolüne girebilir; sözleşme öncesi hukuki görüş alınmazsa izin gecikmesi ve teslim riski doğar.",
"ABD DLA kanalında ihalelerin %72'si yalnızca onaylı kaynaklara açık; ihracat kontrollü teknik veri için gereken JCP sertifikası ABD ve Kanada dışı firmalara verilmiyor.",
"Teknik uyum puanları tesis verisi gelene kadar kamuya açık bilgiye dayalı varsayım; puanlar değişebilir.",
"Yerli ana yüklenicilerin ödeme koşulları KOBİ alt yükleniciler için ağır; 01 kartı ASELSAN için 95 ila 113 gün vade yazıyor."
],
