"aciklama": "155 mm gövde final işleme alt yükleniciliği 21. sıra ve zırh çeliği kesim ile zırhlı gövde alt montajı 20. sıra. İkisinde de giriş engeli 1, süre 1, yatırım 2. İkisi de 3,00 eşiğinin altında. Kartta bu iki puan yok.",
"kaynak": "01 rapor, s_score, Tablo 7.1 verisinden baz ağırlıklarla hesaplandı; s_other 8.9 zırh ön puanı 2,6"
