"puan_metni": "07 ve 08 puan vermiyor, hüküm \"girilir, ama opsiyon olarak\" (29 Eylül 2026). 05'te on iki iş içinde 1. sıra (27 Eylül 2026, sıra numarası; etiketler kaba tahmin). 10 Ek-5'te giren kazanır testi 3/10, 10 üzerinden; Kapı 0, Takvim 1, Alınabilir 1, Boşluk 1, Taban 0 (30 Eylül 2026). 10 puanı sıralama aracı sayıyor, getiri tahmini değil.",
"tarih": "29 Eylül 2026",
"ne": "Ucuz ya da fazla elektriği kum, tuğla, tuz, karbon ya da betonda ısı olarak saklayıp fabrikaya 24 saat buhar ya da sıcak hava veren sistem. Ürün çelik gövde, refrakter, ısıtıcı, eşanjör, buhar üreteci ve otomasyondan oluşur. Rakibi doğalgaz kazanıdır.",
"neden": "Pahalı kısım ısıtıcı, eşanjör, buhar üreteci, gövde ve entegrasyon, yani MEKA'nın bildiği imalat işleri. Depolama malzemesinin kendisi 1-10 $/kWh. Türkiye'de yabancı firmaların temsilcisi de yerli ticari oyuncu da yok, bölge koltuğu boş. En yakın gelir Türkiye'de ısı satmaktan değil, Avrupa projelerine çelik gövde, eşanjör ve konveyör imalatından gelir.",
