"riskler": [
"CBAM yumuşatılabilir, ertelenebilir ya da kapsamı değişebilir; yazar 2026 değişikliklerine bakmadı. Ücretsiz tahsis yavaş kalktığı için klinker tasarrufunun değeri 2027'den geç gelebilir, çıkarım. Yazarın genel dersi: yürürlükte olmayan tarihleri 1-2 yıl kaydırarak değerlendir, 5-7 yıllık geri dönüş planla. 10, A1 Riskler ve Bölüm 3.",
"Doğal kil ve puzolanın kalitesi değişken; yeni çimento tiplerinin standartlarda ve müşteride kabulü yavaş, çıkarım. Kalsine kilde erken hacimler ince: 2023'te dünyada 14 tesis ve %60,9 doluluk. 10, A1 Riskler ve Taban kutusu.",
"Çimento devleri en iyi rezervleri kendine saklar; bağımsız bir tedarikçi rakiplerinin alıcılarına satmak zorunda kalır, çıkarım. Büyükler entegre oluyor: CRH, Holcim, Cimpor, Vicat, Argos, Votorantim. Kalan dilim küresel platform değil, bölgesel rezerv ya da tedarik sözleşmesi. 10, A1 Boşluk kutusu ve Riskler.",
"Bilet ve MEKA payı tahmin: kalsine kil bileti ve MEKA payı doğrulanmadı; kaynaklı tek rakam ABD pazar lideri için 2,1 milyar dolar. 10, Bölüm 9 A1 satırı ve Yöntem sınırları."
],
