"kapsam_notu": "10 numaralı çalışma A1'i ayrı bir alt bölümde beş soruyla puanlıyor; emsal işlem, arz projeksiyonu, kalsine kil tabanı ve Türkiye maruziyeti kaynaklı; bilet ve MEKA payı yazarın tahmini. 09 tek sayfa özeti aynı puanı taşıyor. Taslağın dayandığı 5 Ekim 2026 inceleme dosyası bu turda verilmedi ve klasörde bulunamadı; ona dayanan cümleler çıkarıldı. Web kullanılmadı.",
