"puan_metni": "7 / 10, 30 Eylül 2026 tarihli 5+5 taraması, Liste A, A2. Kutular: Kapı 2, Takvim 2, Alınabilir 1, Boşluk 1, Taban 1. Güven orta. Liste A'da A1 çimento katkısı ve A3 tungsten ile eşit birinci. On alanda 8 / 10 alan B1 PFAS ve B2 jeotermalin ardından; B3 Avrupa depolama hakları da 7 / 10. Puan MEKA uyumunu değil kapı yapısını ölçüyor.",
"tarih": "30 Eylül 2026",
"ne": "SMR ve büyük reaktör programları için emniyet sınıfı basınçlı kap, ısı değiştirici, modül ve tank imal eden atölye işi. Kapıyı makine değil, NQA-1 ya da ASME III kalite programı ve ASME nükleer sertifikası tutuyor. Giriş üç yolla olur: sertifikalı atölye satın almak, bir reaktör tedarikçisinin onaylı imalatçısıyla JV ya da tedarik anlaşması kurmak, ya da kendi ağır atölyende kalite programı ve sertifika kurmak.",
"neden": "Çalışma MEKA tipi işi ağır kaynak, sac şekillendirme, lazer kesim ve hidrolik olarak tanımlıyor. Bir nükleer atölyenin sabit varlığının yüzde 50 ile 70'inin bu tür iş olduğunu tahmin ediyor; bu rakam yazarın tahmini. Yazar açık söylüyor: değer makinede değil, sertifikalı kalite programında, eğitimli kaynakçı ve müfettişte, müşteri onayında. Para süreyi kısaltmaz. Türkiye'de Akkuyu, Sinop için TÜNAŞ ve KEPCO mutabakatı ve ABD ile SMR tasarım çalışması var; konu MEKA'nın yakınında ama kolay değil.",
