"aciklama": "ABD Enerji Bakanlığı DOE, 10'a kadar AP1000 reaktörü için 23 Haziran 2026'da duyurduğu beş şartlı kredinin toplam üst sınırı. Krediler şartlı.",
"kaynak": "10, A2, Takvim ve Taban satırları, kaynak 31 ve 32"
