"durum": "Konu yalnız 30 Eylül 2026 tarihli 5+5 taramasında işlenmiş: 10 numaralı uzun çalışmada A2 bölümü, 09 numaralı tek sayfa özette A2 kartı. Liste A'da en yüksek puanı A1 ve A3 ile paylaşıyor, 7 / 10, güven orta. Bilet gözlemlenebilir değil; satışta bağımsız sertifikalı atölye var mı bilinmiyor; sertifika yolunun maliyeti yayımlanmamış. Çalışmanın Bölüm 7 takviminde A2 için tarih yok; Takvim 2 puanı 13 Nisan ile 29 Eylül 2026 arasındaki geçmiş duyurulara dayanıyor. Henüz adım atılmadı; çalışmanın ilk adımı sertifikalı atölye ve SMR tedarikçi grubu listesi. Bant ikincil: kapı ve devlet destekli talep güçlü, ama bilet belirsiz, ilk gelir 2 ile 4 yıl uzakta ve Türkiye ayağı yazılmamış. Çalışma puanın getiri ya da başarı tahmini olmadığını vurguluyor.",
"acik_sorular": [
"Satışta bağımsız, ASME ya da NQA-1 sertifikalı bir atölye var mı? Sertifika yolunun maliyeti ne? Çalışma ikisini de bilmiyor; Bölüm 9 A2 satırında yazıyor.",
"ANS özetinde anılan Oklo ve ARMEC ile Framatome ve Trillium işlemlerinin tarihleri ne? Çalışma kontrol etmedi.",
"Türkiye'de ASME sertifikalı atölye var mı? MEKA'nın kendi kalite belgesi durumu ne? Çalışmalarda yok.",
"Eskişehir tesisinin tek parçada 10 ton sınırı basınçlı kap ve ağır modül işine yeter mi? 02 ve 03 bu sınırı yazıyor, 10 hiç anmıyor.",
"Batılı bir atölye alınacaksa ABD CFIUS ve İngiltere NSIA denetim eşikleri ne? Çalışma eşikleri doğrulamadı; iki kaynak da tek okuma."
],
