"riskler": [
"Program riski: SMR ve AP1000 siparişleri şartlı ya da fiyatsız. NuScale tasarım sertifikasını 20 Ocak 2023'te aldı ama çıpa projesi UAMPS Kasım 2023'te iptal edildi; bir imalatçının hazırlığı askıda kaldı. NuScale kaynağı Wikipedia, tek okuma.",
"Yavaşlık: kalite programı 9 ile 18 ay, sonra inceleme, tedarikçi denetimi, ilk parça. Kendi atölyede ilk emniyet sınıfı gelire 2 ile 4 yıl, tahmin. Gelir, programların 2030'lar başındaki kilometre taşlarının gerisinden gelir; bu çıkarım.",
"Yabancı alıcıya denetim ve ihracat kontrolü. ABD Donanması işi yapan atölyeler yabancı alıcıya fiilen kapalı olabilir; çıkarım. Akkuyu tedarikçileri Rus normuyla çalışıyor, ASME N damgası ayrı yol.",
"Büyük döküm, forj ve reaktör kapları birkaç firmada toplanıyor; prime'lar kapasite satın alıyor. Orta ölçekli girişçiye kalan dilim alt montaj, tank, ısı değiştirici ve yapısal modül; çıkarım."
],
