"kapsam": "tam",
"kapsam_notu": "10 numaralı çalışma A2 bölümünde konuyu beş soru, süre ve kredi rakamları, tek emsal işlem, üç giriş yolu, riskler, Türkiye açısı ve 27 ile 41 arası 15 kaynakla anlatıyor. 09 tek sayfa özetinde aynı puanla var. 02 ve 03 yalnız 10 ton sınırı için anıldı. 5 Ekim 2026 tarihli inceleme dosyası bu doğrulamada bulunamadı; ona dayanan iddialar çıkarıldı. Web araması yapılmadı.",
