"ne": "Tungsten madenciliği ve konsantre üretimi, ardından APT yani amonyum paratungstat, oksit ve toz üretimi. Alıcılar sert metal, savunma ve endüstriyel takım üreticileri. Giriş yolu junior madencilere hisse koymak, bir işleme tesisi ya da bir maden ruhsatı satın almak.",
"neden": "Liste A tanımı gereği işin sahasında MEKA tipi makine var. Maden ve zenginleştirme ayağında kırma, eleme, konveyör ve gravite ya da flotasyon gerekiyor. Çalışma bu ayakta MEKA makine payını yüzde 40 ile 60 arasında tahmin ediyor. ABD savunma alımlarında 1 Ocak 2027'de tungsten için menşe kısıtı başlıyor; Çin dışı tedarik için tarihi belli bir pencere var. Türkiye'de atıl Uludağ sahası yerli bir giriş noktası olabilir. Ancak çalışma puanı MEKA uyumuna değil kapı yapısına veriyor ve bir yatırım önerisi olmadığını söylüyor.",
