"durum": "30 Eylül 2026 tarihli 5+5 taramasında 7 / 10 aldı; Liste A'da A1 ve A2 ile eşit en yüksek puan. Ön tarama aşamasında. Uludağ ruhsat sahibi ve güncel durumu teyit edilmedi, tungsten için işlem çarpanı bulunamadı, Batı'da baskın oyuncu olup olmadığına bakılmadı. Çalışma A3'ü B4 ağır nadir toprak ile tek bahis sayıyor; ikisi de Çin'in ihracat politikasına ve ABD savunma alımlarına bağlı, Çin gevşerse ikisinde de prim düşer. Bant ikincil kalıyor. Gerekçe: bilet yüzlerce milyon dolar tahmin, ihracat primi politika kaynaklı, Türkiye ayağı teyitsiz, çalışma puanın getiri tahmini olmadığını ve yatırım önerisi vermediğini açıkça yazıyor.",
"acik_sorular": [
"Uludağ sahasının ruhsat sahibi kim, sahanın güncel statüsü ne? Çalışma MAPEG kaydına bakmadı.",
"Tungsten varlıkları için işlem çarpanı ya da emsal fiyat var mı? Çalışma bulamadı; bilet rakamlarının hepsi tahmin.",
"Çin ihracat kontrolleri gevşerse APT fiyatı nereye iner? Yeni bir APT tesisi Çin'in fazla kapasitesi karşısında ayakta kalır mı?",
"Batı'da tungsten madenciliğinde baskın bir oyuncu var mı? Ayrıntılı tarama yapılmadı; Boşluk 2 puanı bu çıkarıma dayanıyor.",
"Yabancı alıcı ve ruhsat devri kuralları ne? Çalışma bunları hukukçuyla teyit edilmeli diyor; Türkiye'de ruhsat devri için MAPEG onayı varsayımı doğrulanmadı.",
"Mining.com'un 3.000 dolar üstü rakamının birimi mtu mu, metrik ton mu? Yazar karışıklık olabileceğini not ediyor."
],
