"riskler": [
"Çin ihracatı gevşerse fiyat normalleşir. Prim Çin'in lisans politikasından geliyor, taban değil. Kontroller gevşeyince Çin APT fazla kapasitesi yeni bir APT tesisini ezebilir. Hepsi çalışmada çıkarım olarak işaretli.",
"Maden ve izin süreleri uzun. Uludağ kaynağı doğrulanmadı, eski tahminler JORC dışı. 1977 tesisi SDE analizine göre yanlış saha, yanlış üretim yöntemi ve yanlış firma ile battı; aynı hata tekrarlanabilir.",
"Bilet büyük: junior hissesi 10 ile 50 milyon Avustralya doları, işleyici 100 ile 450 milyon dolar, rafineri 1 milyar dolar üstü, hepsi tahmin. MEKA'nın mali kapasitesiyle karşılaştırma, getiri, marj ve geri dönüş hesabı çalışmalarda yok.",
"Çalışmanın genel çıkarımı: yürürlükte olmayan tarihleri 1 ile 2 yıl kaydırarak değerlendir, 5 ile 7 yıllık geri dönüş planla, alım garantisi ya da izin güvence altına alınmadan siparişten önce kapasite kurma.",
"Kaynak sağlamlığı: Fastmarkets fiyat kaynağı ve SDE Uludağ analizi kısmen teyit işaretli. Fiyat verisi 19 Haziran 2026 tarihli; 15 Ekim 2026 itibarıyla yaklaşık dört aylık."
],
