"kapsam": "tam",
"kapsam_notu": "10 numaralı çalışma A3 başlığı altında fiyat, bilet, MEKA payı, Uludağ verisi, riskler ve ilk adımı rakamlı ve kaynaklı anlatıyor. 09 özet kartında tek kutu var. Taslağın andığı 5 Ekim 2026 inceleme dosyası verilen kaynaklar arasında yok ve klasörde bulunamadı; ona dayanan bütün atıflar çıkarıldı. Web kullanılmadı.",
