"web": [],
"celiskiler": [
"Çin askısı tarihi 10 Ocak 2027: 10'un A3 bölümü tungsten kontrollerinin ayrı dayanağı var diyerek tarihi B4'e yazıyor; Bölüm 7 takvimi aynı tarihi B4 ve A3 diye veriyor; B4 bölümü A3'ü aynı iki tarihe bağlı sayıyor. 09 özetinde tarih yalnız B4'te.",
"DFARS 1 Ocak 2027: 09 Tarihler listesinde yalnız A3'e yazılmış; 10'un takvimi A3 ve B4 diyor.",
"Fiyat oranı: 10'un A3 Taban satırı ihracat fiyatını Çin iç fiyatının 2,2 ile 2,7 katı veriyor; aynı bölümün Riskler satırı Çin iç fiyatını ihracat fiyatının yaklaşık yarısı diyor. İhracat fiyatı denen rakam CIF Rotterdam ve Baltimore fiyatı; yazar 24 Haziran FOB Çin rakamını ayrı tuttuğunu yazıyor.",
"Boşluk 2 puanı doğrulanmamış çıkarıma dayanıyor; yazar ayrıntılı tarama yapmadım diyor. B2'de benzer bilinmezlik için yazar 1 puan vermiş ve gerekçesini yazmış. Boşluk 1 olsaydı A3 toplamı 6 olur, A4 ve A5 ile eşitlenirdi.",
"Mining.com fiyat haberi: 3.000 dolar üstü rakamın birimi metrik ton yazılmış; yazar mtu ile karışmış olabileceğini not ediyor. Fastmarkets rakamı mtu cinsinden.",
"MEKA payı: 09 özeti yalnız maden ve zenginleştirme varyantını veriyor, yüzde 40 ile 60; işleme kısmının yüzde 15 ile 30 payı yalnız 10'da. Özet tek başına okunursa pay yüksek görünür.",
"Eskiyen veri: tungsten fiyatları Haziran 2026 tarihli, 15 Ekim 2026 itibarıyla yaklaşık dört aylık. Eskime notu derleyenin hesabı.",
"Derleyen notu, çalışmalarda yok: 09 ve 10 A3 ile B4'ü tek bahis saydığı için panoda iki kart birbirine bağlanmalı. 10'un B4 bölümü Türkiye'de Dy ve Tb için doğrulanmış varlık bulamadığını, Beylikova bilgisinin yalnız yazarın araştırma raporunda olduğunu yazıyor."
],
