"İfade farkı: 10 Bölüm 1 zayıf halkaları \"listeleri 5+5 tutmak için yer verdim\" diyor; Bölüm 4 \"en iyi 5'i doldurmak için değil, listeyi dürüst tutmak için ekledim\" diyor. Kaynak: 10 Bölüm 1 ve 4.",
