"tarih": "24 Eylül 2026 ve 25 Eylül 2026",
"ne": "Yıkımdan ve inşaattan çıkan beton, tuğla ve molozu kırıp eleyerek yeniden kullanılabilir agrega üretmek. 03'e göre demir ayrılmalı; mıknatıslı kırıcı ve elek opsiyonu hazır ürün. GPT kartı mevcut ürünleri tekrarlanabilir tesis paketine dönüştürmeyi öneriyor. Suriye'de savaş enkazının sahada kırılıp yeniden inşada kullanılması GPT kartında coğrafi fırsat olarak geçiyor.",
"neden": "GPT kartına göre kırma, eleme, taşıma ve metal ayırma ekipmanı MEKA'da zaten var. 03'e göre mobil kırıcı ve beton santrali mevcut ürün; Ar-Ge gerekmiyor ve yatırım düşük. GPT kartı Hatay'da 500 ton/saat somut tesis talebi veriyor. 03 Suriye'de 8 milyon m³ enkaz hedefi ve BM'nin 570 bin tonluk temizliğini anıyor. İkisi de mevcut ürünle satış fırsatı diyor.",
