"durum": "İki ayrı çalışma konuyu üst sıraya koydu. 24 Eylül 2026 sıralamasında 3., 25 Eylül 2026 GPT kartında kısa vade 1. GPT kartı önerilerin kamuya açık referanslara dayandığını, iç teklif havuzu ve marjlarla doğrulanması gerektiğini söylüyor. Müşteri görüşmesi, malzeme testi ve maliyet çalışması kaynaklarda henüz yapılmış görünmüyor; GPT kartı bunları ilk 30 günün işi olarak veriyor. 03'ün ilk adımı Türk müteahhitlerle görüşmek; ödeme ve yaptırım uyumu önce netleşmeli diyor. Bant ikincil kaldı. GPT'nin kısa vade birinciliği öne çıkan bandı destekler. Ama iki kaynak da koşul koyuyor: Suriye tarafı ödeme ve yaptırım koşuluna, yurt içi tarafı GPT'nin karma moloz test şartına ve müşteri doğrulamasına bağlı. GPT kartının önerdiği 30 günlük doğrulama tamamlanırsa öne çıkan banda geçebilir. 5 Ekim 2026 inceleme dosyası bu doğrulamada verilmedi; ona dayanan ifadeler çıkarıldı.",
