"kaynak": "haber, https://www.ruzgarenerjisi.com.tr/enerji-bakanligi-yeka-res-2026-yarismalarini-ilan-etti/ ; haber, https://dunyaenerji.org.tr/gunes-ve-ruzgar-enerjisine-dayali-yeka-yarismalarina-basvurular-13-ekimde-alinacak/ (AA aktarımı) ; haber, https://www.bloomberght.com/yeka-da-basvurular-alindi-22-yila-varan-kredi-imkani-motivasyonu-artiriyor-3791225"
