"neden: Bunker, konveyör, sac gövde ve otomasyon benzerliği ile agreganın ham madde olduğu cümleleri çıkarıldı; çalışmalarda yok. Gerekçe Belge 03'ün tek cümlesiyle sınırlandı.",
"rakamlar: Etiket rakamına Belge 03'ün kaba tahmin uyarısı eklendi. Üç web rakamına çalışmalarda yok ve bu turda yeniden doğrulanmadı notu eklendi. E-MAK Danimarka satışı için eksik olan worldhighways URL'si kaynağa eklendi.",
"durum: 5 Ekim 2026 incelemesine dayanan cümle çıkarıldı; inceleme dosyası tura verilmedi. Belge 05'in ölçütünün MEKA'dan bağımsız işler olduğu ve bu yüzden asfaltın orada olmamasının beklendiği eklendi. Belge 03'ün yakın takviminin asfaltı içermediği eklendi.",
"riskler: Marini çıkarıldı; hiçbir kaynakta ve web listesinde yok. Polygonmach bilgisi web listesindeki agriline kaydına bağlandı. Etiketlerin kaba tahmin olduğu riski eklendi.",
"yol_not: İnceleme giriş yolunu şirket satın alma olarak yazıyor ifadesi çıkarıldı; inceleme dosyası verilmedi.",
"takvim: Kaynaktan inceleme referansı çıkarıldı; Belge 03 yakın takviminin içeriği eklendi.",
"kaynaklar: İnceleme kaydı çıkarıldı. Belge 05 bölüm adı dosyadaki gerçek başlıkla değiştirildi: Taştan tozdan farklı: on iki iş, tek sıra. Belge 03 kaydına Önermediklerimiz ve Yakın takvim bölümleri eklendi.",
"celiskiler: İncelemeye dayanan iki madde çıkarıldı; kalan maddeler Belge 03 metninden türetilir biçimde yeniden yazıldı. Marini çıkarıldı.",
