"8 milyon ton 'yaklaşık' olarak düzeltildi; belge 05'teki Nitrat Tebliği 2025/17 eklendi; ÇŞB sunumunun 2023 tarihi kaynak adresinden okunduğu belirtildi.",
"Batarya tesisi: 'Türkiye'nin ilk tesislerinden biri' ifadesi kaynaktaki gibi 'ilk tesislerden biri' yapıldı; kaynak başlığındaki Dilovası OSB ve 864 milyon TL eklendi.",
"Ay madenciliği için Interlune ve Vermeer örneği rakamsız kalem olarak eklendi.",
