"Bazalt adımı yumuşatıldı: hedef müşteriyi değiştirme kararı doğrulanmamış web bulgusuna dayanıyordu; önce girişimlere sorma adımı yapıldı.",
"Tavuk gübresi adımındaki '31 Aralık 2025 sonrası' ifadesi kaldırıldı; EPDK teyidi genel yazıldı. Açık sorulara 419 kr/kWh geçerlilik sorusu eklendi.",
