"kaynak": "firma beyanı, doğrulandı: https://milvusrobotics.com/newsroom/milvus-robotics-secures-4-5-million-in-funding-to-accelerate-global-expansion ; haber açılmadı: https://egirisim.com/2025/05/27/ankarada-kurulan-milvus-robotics-4-5-milyon-dolar-yatirim-aldi/"
