"kaynak": "firma beyanı ve haber, doğrulandı: https://milvusrobotics.com/blog/series-a-funding-to-5-5-million ve https://www.paradergi.com.tr/girisimcilik/2025/10/23/dunyanin-robotunu-uretecek"
