"riskler": [
"Tedarik cirosu küçük: robot başına 3 ile 4 bin dolar sac işi varsayımıyla yılda 1.000 robotta bile 3 ile 4 milyon dolar; MEKA ölçeğinde yan iş. Varsayım, şirket rakamı değil.",
"Robot gövdesi ince sac ve hassas montaj işi; MEKA'nın ağır sac hattına uymayabilir, ek yatırım gerektirebilir.",
"Şirket kendi fabrikasını kuruyor; gövde ve şasiyi içeride yapmayı seçebilir.",
"Rakamların çoğu şirketin kendi beyanı; ciro, adet ve kârlılık bilinmiyor.",
"İçeride altı fon var; azınlık pay için fiyat ve koşulları fonlar belirler.",
"Küresel AMR pazarında çok sayıda rakip ve Çinli üreticilerin fiyat baskısı; Tracxn'in 800'den fazla rakip sayısı bu turda doğrulanamadı.",
"Fabrika hedefinin 2026 sonunda gerçekleşmemesi halinde kapasite ve tedarik planı kayar."
],
