"Mayıs 2025 duyurusunun alt metnindeki '15'ten fazla ülke' ifadesinin aynı sayfada gövde metindeki '20'den fazla' ile birlikte yer aldığı netleştirildi.",
"Comau sayfasındaki 'Comau'nun kalite standartlarına göre' ifadesi eklendi; üretici belirtilmediği korundu.",
"F1500S rakamlarına lb ve ft karşılıkları eklendi; 'piyasadaki en hızlı forklift AMR' ve 98,9 / 35 / 14 ay rakamları firma beyanı diye işaretlendi; Robotics Tomorrow metninin basın bülteni niteliğinde olduğu not edildi.",
"Para Dergi'den iki yeni bilgi eklendi: CEO'nun 'yeni yatırım turları gündemimizde olabilir' sözü ve Seri A kaynağının üç kullanım alanı.",
"Takvime 5 Kasım 2025 Teknogirişim rozeti ve 20 Nisan 2026 Robotics Tomorrow haberi eklendi.",
"Doğrulanan rakamlar (600 bin, 4,5 milyon, 5,5 milyon, 98 çalışan, 450 robot, 41 lokasyon, 1.700 kapasite, 1.500 kg, 2,70 m, Fast Company 7. sıra, Comau 13 Nisan 2026) 'doğrulandı' diye işaretlendi.",
"Açılmayan haber kaynakları (egirişim, Webrazzi 2025, Robotics 24/7, Forkliftaction) web listesinde ve kaynaklarda 'bu turda açılmadı' diye işaretlendi.",
