"rakamlar'a 06 dipnotundaki robot fiyatı varsayımı (40 bin $, piyasada 10-100 bin $) ve ortaklık dipnotundaki 50 M$ değerleme, %4 pay varsayımı eklendi.",
"durum'a 06'nın 'Taslak' etiketi ve 'tablolar varsayımdır' uyarısı eklendi; 'gecikti' hükmü 'yapıldığına dair kayıt dosyalarda yok' olarak yumuşatıldı.",
