"Belge 04 Novator için erken aşama, yatırım geçmişi teyit edilecek der ve şirketlerle konuşmadan hiçbirine yatırım yapılmalı demiyoruz diye ekler. Aynı gün tarihli Belge 05 onu 4. sıraya koyar ve ilk ortak biz oluruz der.",
"Depolama ön lisans rakamı iki belgede farklı: Belge 05 madde 4'te 38 GW, Belge 04 kaynak 10 başlığında 25,6 GW. Novator maddesinin talep gerekçesi bu rakama dayanıyor.",
"MEKA'dan bağımsız ölçütü ile metin tutarsız: Belge 05 Novator için MEKA katkısı pano, konteyner, otomasyon yazar ve strateji 2. adımda üretimi MEKA'ya alır.",
"Belge 05'teki 0-6 ay etiketi diğer maddelerde ticarileşme süresi iken burada yatırım işleminin süresi gibi okunuyor; aynı belgenin harita notu şirket yatırımında getiri geç ama büyük olabilir der.",
