"butce_not": "INVEST101 bileti 250 bin ile 1 milyon dolar; 05'te tek şirkete azınlık payı için yatırım etiketi küçük, 04'teki küçük dilim 1 milyon dolar altı. ODTÜ70 asgari katılım çalışmalarda yok. İlk temas ve teyit için 1. dilim yeter. Varsayım.",
"yol": "ortak",
"yol_not": "04 sayfa 2 açıkça fabrika kurmadan ortak olmayı anlatıyor: fon payı, melek yatırım ya da yan yana yatırım. 05 şirket yatırımı için önce ortak sonra sahip stratejisi veriyor: %25 altı pay, pilot, bölge lisansı, ön alım hakkı. Hidrojen tankı kurmak 3 yıldan uzun, Ar-Ge yüksek, yatırım büyük; bu yüzden yalnız TEKSİS üzerinden izlenir. Yatırım kapısı için 04 iki seçeneği de açık bırakıyor: MEKA üzerinden KAP bildirimi, kişisel yolda melek teşviki."
