"id": "jeotermal",
"baslik": "Jeotermal ruhsat ihaleleri (Türkiye)",
"bant": "izle",
"puan_metni": "8 / 10, 5+5 çalışması, 10 üzerinden. Kutular Kapı 2, Takvim 2, Alınabilir 2, Boşluk 1, Taban 1. On alan içinde B1 PFAS ile birlikte en yüksek puan. Yazarın güven notu: kapı ve takvim orta, ekonomi düşük. Puan kapı yapısını ölçüyor; getiri ya da başarı tahmini değil. Puanlama eşit ağırlıklı ve yazarın kendi puanı; bir puan değişirse sıra değişir.",
"tarih": "30 Eylül 2026",
"ne": "İl özel idareleri ve valilikler jeotermal kaynak arama ruhsat sahalarını tek tek ihaleye çıkarıyor. İhaleyi kazanan o sahada arama ruhsatını alıyor; çalışma bunu sahaya münhasır hak diye tanımlıyor. Münhasırlığın ayrıntısı, süre ve işletme ruhsatına geçiş, mevzuat metninden okunmadı. Sondaj, santral ve şebeke bağlantısı ayrı iş ve ruhsat bedelinden çok daha büyük yatırımlar.",
"neden": "Giren kazanır taramasının ana bulgusu şu: kapıyı makine değil hak tutuyor. Burada hak devletin ihalesiyle veriliyor ve ilk bilet küçük; muhammen bedel saha başına yaklaşık 1 ile 2 milyon TL, teminat onbinlerce TL. Çalışma B2'yi A1 ile birlikte ilk adımı en ucuz iki alan arasında sayıyor. İş MEKA makinesi gerektirmiyor; Liste B'de. Alanın tamamı Türkiye'de ve Erzurum ilanı Türk vatandaşları, Türk şirketleri ve kamu iktisadi teşebbüslerine açık. Çalışma alanlara MEKA'dan bağımsız baktı; yatırımın kimin üzerinden yapılacağı çalışmada yok.",
