"puan_metni": "7 / 10, 5+5 çalışması, 10 üzerinden. Kapı 2, Takvim 2, Alınabilir 1, Boşluk 1, Taban 1. Bu puan Almanya satırının puanı. İspanya 7, İngiltere 7, İtalya 6; dört ülke ortalaması 6,75. Güven düşük-orta. Puan 09 ve 10 çalışmalarında var; başka dosyaya bakılmadı.",
"tarih": "30 Eylül 2026",
"ne": "Avrupa'daki batarya ve uzun süreli depolama projelerinin tuttuğu hakları satın almak ya da bu projelere ortak olmak. Hak üç biçimde geliyor: şebeke bağlantı sırası, kapasite piyasası ya da prim sözleşmesi, gelir tabanı. Hak dağıtıldıktan sonra gelenler daha kötü koşul alıyor. 10 numaralı çalışma bunu Polonya örneğiyle gösteriyor ve çıkarım diye işaretliyor.",
"neden": "Bu iş Liste B'de, yani işin sahasında MEKA makinesi gerekmiyor. 5+5 çalışmasının ana bulgusu şu: kapıyı makine değil hak tutuyor. Avrupa depolama hakları bu bulgunun tarihli pencereleri olan örneği. Türkiye'de depolamalı yeni ön lisans başvuruları 14 Ekim 2023'ten beri durdurulmuş; 10 numaralı çalışma bu havuzu kapalı kulüp ve alıcı pazarı diye niteliyor, çıkarım olarak. Avrupa'da ise 30 Eylül 2026 itibarıyla Almanya ve İngiltere'de tarihli tur vardı. Bu yüzden MEKA için üretim işi değil, sermaye ile hak tutma pozisyonu. Bu son cümle çalışmanın değil, bu özetin çıkarımı.",
