"durum": "Kaynağın durum tarihi 30 Eylül 2026; sonrası için dosyalarda bilgi yok. O tarihte dört ülkede de yeni girişçiye açık bir pencere yok. Almanya 1. tur 30 Haziran 2026'da kapandı, 2. tur tarihsiz. İspanya ilk ihale tarihsiz. İngiltere Pencere 1'de 16 proje seçildi; Pencere 2 tasarım kararı 2027'de bekleniyor. İtalya MACSE-2 başvuru kabulü kapandı; 24 Kasım 2026 ihalesi yalnız kabul edilmiş projeler arasında yapılacak. Bant izle, çünkü 10 numaralı çalışmanın kendi hükmü şu: Almanya 2. tur ve İspanya ilk ihale tarihi çıkana kadar bu alan izleme listesinde. Puan 7 / 10 ile ikinci kademede olsa da çalışmanın bu hükmü puanın önüne geçiyor.",
