"puan_metni": "6 / 10, Belge 10 Giren Kazanır 5+5 çalışması, 30 Eylül 2026. Beş soru, her biri 0 ile 2 puan: Kapı 1, Takvim 1, Alınabilir 2, Boşluk 1, Taban 1. Liste B, yani sahada MEKA makinesi gerekmeyen beş alanın sonuncusu. On alan içinde 6 / 10 alan dört alandan biri. Yazar \"zayıf halka\" işareti koymuş, güven düşük-orta. Puan bir sıralama aracı; getiri ya da başarı tahmini değil. MEKA'ya uyum puana katılmamış.",
