"durum": "30 Eylül 2026 tarihli Belge 10'da Liste B'nin son sırasında, 6 / 10 ve \"zayıf halka\" işaretli. Yazar listeyi 5+5 tutmak için yer verdiğini açıkça yazıyor; güven düşük-orta. Türkiye'de semaglutid patent durumu, TİTCK fiili ruhsat süresi ve SGK listeleme takvimi doğrulanmadı; yazar bunlar çıkmadan puanın yükselmeyeceğini söylüyor. 2025 ile 2026'da somut bir lisans anlaşması bulunamadı. Ön bant \"izle\" korunuyor: çalışma alanı açıkça elemiyor, ama ilk giren avantajı bulmuyor ve kapı yapısını zayıf görüyor. Belge 09 aynı puanı ve aynı ilk adımı veriyor. 5 Ekim 2026 incelemesi verilen kaynak dosyalar arasında yok; ona dayanan ifadeler çıkarıldı.",
