"OVP 2027-2029'daki sağlıkta uzun vadeli alım garantisi iddiası birincil metinde var mı? Yazar PDF'nin yalnız ilk yaklaşık 15 sayfasını okuyabildi, sağlık metnini bulamadı. İddia 8 Eylül 2026 tarihli ikincil haberden.",
"TİTCK ruhsat süresi ve SGK listeleme takvimi fiilen ne kadar sürüyor? TİTCK ruhsat devri kuralları ve Rekabet Kurulu bildirim eşikleri ne? Yabancı alıcıya özel ilaç sınırı IBA anketinde geçmiyor; çalışma doğrulamadı.",
"Biyolojik segmentin kendi büyüklüğü nedir ve en büyük ithal kalemlerde hangi yerli firmalar üretim planlıyor? Çalışmadaki rakamlar toplam ilaç pazarı; yazar Boşluk puanını bu bilinmeyen yüzünden 1 vermiş.",
"Deva ve TRILC kartlarının tarihi ne? Sanovel'in Mart 2026'daki satış fiyatı ne? Çalışmada ikisi de yok."
