"kapsam": "tam",
"kapsam_notu": "Belge 10 konuyu beş soru puanıyla, TÜSEB pazar ve ithalat rakamlarıyla, Fiyat Kararı 11031 ile ve hedef şirket değerlemeleriyle gerekçeli anlatıyor; 14 kaynak gösteriyor. Belge 09 aynı puanı ve ana rakamları tek paragrafta özetliyor. Web araması yapılmadı. 5 Ekim 2026 incelemesi verilen kaynaklar arasında yok, kullanılmadı.",
"kanit": 3,
"web": [],
"celiskiler": [
"Puan cetveli ile verilen puan uyuşmuyor. Belge 10 Bölüm 2 cetvelinde Takvim sorusunda 'tarih yok' 0 puan karşılığı. B5 Takvim satırı 'sabit bir tetik tarih yok' deyip 1 puan veriyor. Cetvele göre toplam 5 olurdu. Kaynak: 10, Bölüm 2 Yöntem ve Liste B, B5 Takvim satırı.",
"Başlık 'biyolojik' ama rakamlar toplam ilaç pazarı. Biyolojik segmentin büyüklüğü, yerli rakiplerin planı ve 2025 ile 2026'da somut bir lisans anlaşması yok. Yazar bunu kendisi yazıyor. Kaynak: 10, Liste B, B5, Boşluk satırı ve Giriş yolu ve bilet.",
"Pazar 9,9 Mrd$, ithalat 6,22 Mrd$ ve yerli pay %57,6 aynı tabanda bağdaşmıyor; 6,22 bölü 9,9 yaklaşık %63 eder. Tanım farkı çalışmada açıklanmamış. Kaynak: 10, Liste B, B5, Kanıt ve tarihler; benim hesabım.",
"Zayıf halkaların listede olma nedeni iki türlü anlatılıyor. Bölüm 1 Özet ve B5 bölümü 'listeleri 5+5 tutmak için yer verdim' diyor. Bölüm 4 'en iyi 5'i doldurmak için değil, listeyi dürüst tutmak için ekledim' diyor. Kaynak: 10, Bölüm 1, Bölüm 4 ve Liste B, B5.",
"Bölüm 1 Özet 'baktığım 10 pencerenin hepsinde kapıyı bir hak ya da yeterlilik tutuyor' diyor. B5 bölümü 'kapı bir hak değil, süre ve geri ödeme' yazıyor. Bölüm 4 da A4, A5 ve B5'te gerçek bir kapı yok diyor. Kaynak: 10, Bölüm 1 ve Liste B, B5.",
"Belge 09 Avro katsayısı ve eşdeğer tavanı rakamlarını veriyor ama %39 çarpımını, IVIG hesabını ve Deva ile TRILC değerlemelerini içermiyor. Çelişki değil, kapsam farkı. Kaynak: 09, B5 ve 10, Liste B, B5."
],
"degisiklikler": [
"5 Ekim 2026 incelemesine yapılan bütün atıflar çıkarıldı: durum, takvim 4 ve 5, kaynaklar üçüncü madde, çelişkiler 1 ile 6. Bu dosya verilen kaynak dosyalar arasında yok ve klasörde bulunamadı.",
"Çelişkiler 1, 2, 3, 4 ve 5 Belge 10 metninde doğrudan doğrulandı; kaynak atıfları Belge 10'un bölüm adlarına çevrildi. Ağaç yerleşimi çelişkisi silindi; yalnız incelemeye dayanıyordu.",
"Çelişkilere Belge 09 ile Belge 10 arasındaki kapsam farkı eklendi.",
"puan_metni'ne 'MEKA'ya uyum puana katılmamış' ve 'on alan içinde 6 / 10 alan dört alandan biri' eklendi; Belge 10 Bölüm 1 ve 2.",
"neden alanına 'eşdeğer ürünlerde münhasırlık yok' ve 'tarihli bir tetik yok' eklendi; Belge 10 B5 Kapı satırı ve Neden zayıf halka.",
"rakamlar: 29,1164 TL avro değeri ve FDA 80 biyobenzer satırı eklendi. Deva ve TRILC satırına TL değerleri 18,4 Mrd TL ve 1,09 Mrd TL ve 'FAVÖK'e EV çarpanı' ifadesi eklendi. IVIG satırına %86,46 payı eklendi. Kaynak atıflarına Belge 10 kaynak numaraları eklendi.",
"takvim: 24 Mart 2026 Sanovel satış haberi eklendi. 'Tarih yok' satırına Bölüm 7 takvim tablosunda B5 satırı olmadığı notu eklendi. OVP satırına ikincil haberin tarihi 8 Eylül 2026 eklendi.",
"acik_sorular: semaglutid sorusuna SPC notu eklendi; TİTCK sorusuna Rekabet Kurulu eşikleri ve IBA notu eklendi; Deva, TRILC ve Sanovel tarih sorusu eklendi.",
"adimlar: Belge 09 Sınırlar bölümündeki 'yabancı alıcı ve ruhsat devri kurallarını hukukçuyla teyit' adımı eklendi. Kişi ve tarih alanlarına 'çalışmada yok, öneri' notu eklendi.",
"riskler: SGK riskine 'çıkarım' işareti, biyobenzer kalabalığına Hindistan 17 jenerik notu, değerlemelerin tarihsizliği ve puan ağırlığı riski eklendi; Belge 10 B5 Riskler ve Bölüm 9 Yöntem sınırları.",
"kaynaklar: Belge 10 bölüm adları dosyadaki gerçek başlıklarla yazıldı: '6. Liste B: MEKA'sız', '1. Özet', '2. Yöntem', '4. Sıralama: iki liste, 5 + 5', '7. Takvim', '9. Sınırlar: bilmediklerim ve nasıl okunmalı', '10. Kaynaklar'. Belge 09'a Sınırlar bölümü eklendi.",
"kapsam_notu'na Belge 10'un 14 kaynak gösterdiği ve incelemenin kullanılmadığı yazıldı.",
"Puanlar, tarihler, kapılar, bant ve tam_calisma başlıkları kaynaklarla doğrulandı; değiştirilmedi."
],
