"bant": "elendi",
"puan_metni": "Bant 16 Ekim 2026 ek araştırmasıyla elendi yapıldı (önce izle): Açık çağrı yok, OTAĞ katılımı 10 Ekim 2025'te kapandı (resmi sayfada doğrulandı), sonuç raporu portalda yok (doğrulandı) ve pazar birkaç TSKGV iştiraki ile uzman firmada toplanıyor. MEKA'nın hücre ve BMS yetkinliği yok; tek gerçekçi iş batarya paket kasası ve konteyner sac işi, o da ayrı bir yaprak değil, savunma sac nişinin alt kalemi. Yaprak kapatılıp iki görüşmeyle doğrulanmalı. Önceki puan notu: Puan yok. 30 Eylül 2026 tarihli 5+5 çalışması 10 üzerinden kapı testini savunma bataryasına uygulamadı. Ek-2'nin hükmü yalnız şu: offset, Sanayileşme projeleri ve OTAĞ olmak üzere üç ortaklık kanalı var, hiçbiri açık teklif çağrısı değil; kanal sayımı çalışmada çıkarım diye işaretli. Aynı çalışmanın Ek-5 bölümünde komşu konular 10 üzerinden: termal batarya 3, Türkiye lityum entegrasyonu 2, ikincisi çıkarım.",
"tarih": "16 Ekim 2026 (ek araştırma); önceki çalışma 30 Eylül 2026",
"ne": "Savunma Sanayii Başkanlığı 10 Eylül 2025'te Batarya Teknolojileri Odak Teknoloji Ağı'nı başlattı. Amaç savunma bataryaları için yol haritası çıkarmak. Katılım formu 10 Ekim 2025'te kapandı. 16 Ekim 2026 itibarıyla SSB Ar-Ge portalında batarya OTAĞ'ı ne tamamlanan ne devam eden listede; sonuç raporu görünmüyor. SSB duyurularında bataryaya özel çağrı bulunmadı (duyuru listesi bu turda yeniden açılmadı). Yerli oyuncular ASPİLSAN, Altınay ve birkaç paket üreticisi; iş hücre, BMS ve paket entegrasyonu. MEKA'nın bu alanda yetkinliği yok.",
"neden": "Önceki çalışma konuyu bir iki cümleyle geçmiş ve OTAĞ yol haritasını açık soru bırakmıştı. Karar ağacında yaprağın kalıp kalmayacağı için açık çağrı, katılım koşulu ve pazar büyüklüğü kanıtı gerekiyordu.",
