"durum": "OTAĞ başladı, katılım kapandı, 16 Ekim 2026'da SSB Ar-Ge portalında batarya OTAĞ'ı ne tamamlanan ne devam eden listede. Önceki turda okunan SSB duyuru listesinde 2025 ve 2026'da bataryaya özel çağrı yoktu; liste bu turda yeniden açılmadı. Türkiye'de savunma batarya işi ASPİLSAN, Altınay ve birkaç paket üreticisinde; yerlileştirme offset sözleşmeleriyle yürüyor. EYDEP tedarikçi yetkinlik sertifikası; batarya programı değil. SAYP tanımı doğrulanamadı.",
"acik_sorular": [
"Batarya OTAĞ sonuç raporu ne zaman yayımlanacak ve içinde paket kasası, soğutma plakası gibi mekanik yerlileştirme kalemi olacak mı",
"ASPİLSAN ve Altınay batarya paket kasası ve mekanik parçaları kimden alıyor; dış tedarik var mı",
"SSB Sanayi Katılımı Offset programında büyük sanayi firması için sac ve mekanik işler kategorisi tanımlı mı",
"Türkiye savunma batarya pazarının toplam büyüklüğü için resmi ya da dernek kaynaklı rakam var mı",
"13 Temmuz 2026 tarihli SSB kredi talebi çağrısının koşulları ve süresi ne (çağrı kaydı bu turda doğrulanmadı)"
],
