"puan_metni": "10 üzerinden 8, Belge 10 Giren Kazanır 5+5 kapı testi, 30 Eylül 2026. Kutular: Kapı 2, Takvim 2, Alınabilir 2, Boşluk 1, Taban 1. B2 Türkiye jeotermal ruhsat ihaleleri ile birlikte on alanda en yüksek puan. Güven orta. Yazar Takvim puanını en tartışmalı sayıyor; 1 olursa toplam 7. Puan eşit ağırlıklı bir sıralama aracı, getiri ya da başarı tahmini değil; MEKA'ya uyum puana katılmadı.",
"tarih": "30 Eylül 2026",
"ne": "PFAS, yani sonsuz kimyasallar içeren atıkları yoğunlaştırmak, yok etmek ya da güvenle depolamak için izinli kapasiteye sahip olmak. Atık kullanılmış aktif karbon ve reçine, ters ozmoz konsantresi, çöplük sızıntı suyu, yangın söndürme köpüğü ve sanayi atık suyundan geliyor. Üç kapasite türü var: tehlikeli atık yakma, aktif karbon reaktivasyonu ve yakma dışı imha teknolojileri. Kapıyı bu kapasitenin izni tutuyor.",
"neden": "Giren kazanır taramasında on alan içinde B2 ile birlikte en yüksek puanı aldı. Puan kapı ve takvim yapısından geliyor: kapı para ile tek başına alınamayan bir izin ve önünde tarihi belli bir pencere var. İzinli tesisler bugün tehlikeli atık geliri kazanıyor; Clean Harbors yakma tesislerini yüzde 91 dolulukla işletiyor. Yazar bunu \"bugün para kazanan bir varlık al, yeni kuralı opsiyon say\" örneği olarak veriyor. Mehmet Bey için anlamı MEKA işinden bağımsız bir varlık yatırımı: sahada MEKA makinesi gerekmiyor, iş ABD ya da AB'de izinli bir işletme almak ya da ortak olmak. Yazar ekonomiyi belirsiz sayıyor; sözleşmeli taban yok.",
