"kapsam": "tam",
"kapsam_notu": "Belge 10 konuyu beş soruyla puanlıyor; emsal işlem, doluluk oranı, EPA rehberi, ABD tarihleri, giriş yolları ve riskler kaynaklı veriliyor. Belge 09 aynı bilginin tek sayfa özeti. Web kullanılmadı. 5 Ekim 2026 inceleme dosyası bu çalışmada verilmedi ve bulunamadı; ona dayanan ifadeler çıkarıldı.",
