"celiskiler": [
"09 özet kartında B1'in Türkiye dışında, ABD ya da AB'de bir varlık alımı olacağı ve 305 M$ emsalin PFAS'a özel olmadığı yazmıyor; bu iki nokta yalnız 10'da var. Kaynak: 09, B1 kartı; 10, Bölüm 6 B1, Alınabilir satırı ve Türkiye açısı.",
"On alanın puanı 6 ile 8 arasına sıkışmış. Yazar B1'in Takvim puanını en tartışmalı sayıyor; 1 olursa toplam 7 olur ve B1 yedi puanlı dört alanla eşitlenir. Kaynak: 10, Bölüm 4 Sıralama; Bölüm 6 B1, Takvim satırı; Bölüm 9 Yöntem sınırları.",
"305 M$ biletin MEKA için anlamı çalışmada tartışılmıyor; B listesinde MEKA payı hesaplanmamış; MEKA bilançosu ve nakdi çalışmalarda yok. Kaynak: 10, Bölüm 6 Liste B giriş; Bölüm 6 B1, Giriş yolu ve bilet.",
"B1 için satılık hedef listesi yok; Clean Harbors dışındaki büyük yakma işletmecileri doğrulanmamış; AB tarihi açılamayan kaynakta; Türkiye'de PFAS sınırı ve yakma kapasitesi doğrulanmamış. Kaynak: 10, Bölüm 6 B1, Boşluk satırı ve Türkiye açısı; Bölüm 9 Sınırlar; Kaynaklar 59.",
"Başlık ABD ve AB diyor; yakma dışı teknoloji kaynağı ABD'yi tek aktif pazar diye anıyor ve AB için çalışmada yalnız doğrulanamayan bir tarih var. Kaynak: 10, Bölüm 6 B1, Boşluk ve Takvim satırları; Kaynaklar 59, 60."
],
