"ne": "Disprosyum, terbiyum ve itriyum gibi ağır nadir toprak elementlerinin Çin dışında ayrıştırılması, ayrıca metal ve alaşım üretimi. Müşteri mıknatıs üreticileri, savunma ve havacılık sanayii. Giriş yolu alım garantisiyle azınlık payı, küçük bir özel işleme firmasının alınması ya da hammadde ortaklığı.",
"neden": "Çin dışı ağır nadir toprak fiyatı Çin içi fiyatın katları; Benchmark 25 Eylül 2026'da disprosyum oksit için 16,3 kat yazıyor. Devlet kredisi ve alım garantisi kanalı açık: MP Materials 2025'te ABD Savunma Bakanlığı'ndan 400 M$ ve 110 $/kg NdPr taban fiyatı aldı; Energy Fuels Utah'taki metal tesisi için ABD Savunma Bakanlığı Stratejik Sermaye Ofisi'nden şartlı 725 M$ kredi aldı. Bu kredi 10 numaralı çalışmada Bölüm 3 ve A3 bölümünde geçiyor, B4 bölümünde değil. Çalışma bu alanı B listesine koyuyor, yani işin sahasında MEKA makinesi gerekmiyor; alan MEKA'dan bağımsız, hak ve pay alma yoluyla girilecek bir pencere olarak ele alınmış.",
