"durum": "30 Eylül 2026 tarihli 5+5 taramasında Liste B'de 6 / 10 puanla B4 sırasında, güven orta; zayıf halka olarak işaretlenmedi. Çalışma bu alanı A3 tungsten ile tek bahis sayıyor, ikisi de Çin ihracat politikasına ve ABD savunma alımlarına bağlı. Türkiye'de Dy ve Tb için doğrulanmış bir varlık bulunamadı; Beylikova yalnız doğrulanmamış araştırma raporundan biliniyor, hafif nadir toprak ağırlıklı görünüyor ve kaynak listesine alınmadı. İki kaynak dosyada atılmış bir adım yok. Bant ikincil kalıyor: tarihli penceresi ve emsal işlemi var, ama bilet yüzlerce milyon dolar, Dy ve Tb için taban yok ve prim Çin politikasına bağlı.",
