"puan_metni": "05 tek sırasında 12 iş içinde 3., 27 Eylül 2026, sıra numarası, puan yok. 04 taramasında 7 iş içinde 3., 27 Eylül 2026, sıra numarası. 10 Ek-5 giren kazanır testinde lityum entegrasyonu Türkiye 2/10, 30 Eylül 2026, 10 üzerinden, çıkarım işaretli; çalışmadaki en düşük puan, termal batarya 3/10, ana liste en düşük 6/10.",
"tarih": "30 Eylül 2026; fabrika ölçeği fikri 27 Eylül 2026",
"ne": "Fabrikanın kendi güneşine batarya kurup işletmek ve enerjiyi hizmet olarak satmak. 04 hücre için yerli tedarikçi diyor ve ithal LFP vergisini anıyor; hücre tipi başka yazılmamış. 10 aynı başlık altında Türkiye'de lityum-iyon hücre üretimi, montaj hattı ve şebeke ölçeğinde depolama entegrasyonunu inceledi.",
"neden": "MEKA işinden bağımsız bir alan; Mehmet Bey'in bağımsız ve teknolojik ölçütüne giriyor. 1 Mayıs 2026'dan beri lisanssız GES'te saatlik mahsuplaşma var ve kurulu güce kadar depolama serbest; OSB'lere de depolama izni verildi. İthal LFP'ye yüzde 30 ek vergi yerli montajı koruyor. 04 ve 05 bu yüzden konuyu gelire yakın, Ar-Ge düşük bir iş olarak 3. sıraya koydu.",
