"durum": "27 Eylül 2026'da 04 konuyu 7 iş içinde, 05 ise 12 iş içinde 3. sıraya koydu; ilk adım 2 ya da 3 fabrikayla pilot. 30 Eylül 2026'da 10 aynı işin lityum entegrasyonu halini giren kazanır testinde 2/10 ile en alta koydu: kapı yok, Çin fiyatı 73 dolar/kWh, entegratör marjı yüzde 3,3. Yerli emsaller zor durumda: Pomega ve Kontrolmatik borç yapılandırmasında, Solinved seri üretimi doğrulanmadı, 82 lisanslı tesisten 8'i işletmede. Ön bant ikincil yerine izle, çünkü en yeni çalışma kapı ve marj yok diyor. 05'in eldeki sürümü 27 Eylül 2026 tarihli; 10'dan sonra güncellenmiş bir sürüm çalışmalarda yok. 10'un testi fabrika ölçeğinde hizmet olarak enerji modelini ayrıca ele almıyor; o yol kapanmadı, test edilmedi. Çalışmalarda temas ya da pilot kaydı yok.",
"acik_sorular": [
"Fabrika ölçeğinde hizmet olarak enerji modeli 10'un entegrasyon testinden ayrı sayılacak mı; fabrika için tarife farkı, mahsuplaşma kazancı ve geri ödeme hesabı yapılacak mı? Çalışmalarda yok.",
"Solinved seri üretime geçti mi; pilot için yerli hücre tedarikçisi kim olur: Solinved, Pomega ya da 2027'de ASPİLSAN LFP hattı? 10, Ek için sonraki adımlar ve Ek-1.",
"Pomega ve Kontrolmatik hangi varlıkları hangi fiyattan satacak; bu bir alım fırsatı mı? 10, Ek-1 ve Ek-5.",
"Yatırım MEKA üzerinden mi, kişisel mi? MEKA borsada olduğu için şirket yatırımı KAP'a bildirilir; kişisel yatırımda melek teşviki var. 04 ve 05 soruyu Mehmet Bey'e açık bırakıyor."
],
