"celiskiler": [
"Önceki çalışma 'sektör 800 W bildirimle serbest kuralını bekliyor' dedi. Kaynak olan 6 Mayıs 2026 tarihli CRB Haber yazısı EPDK'ya atıf yapmıyor; ifade yazarın kendi önerisi (bu turda yeniden açılmadı).",
"Almanya kayıtlı sistem sayısı üç farklı değerle geçiyor: 1,33 milyon (önceki çalışma, gfk-solar), 1,32 milyondan fazla (Lifeverde, Mayıs 2026, doğrulandı), 1,3 milyonu aşan (SolarGazete, Nisan 2026, bu turda açılmadı). Resmi MaStR sayısı doğrulanamadı.",
"Aydem blogu 800 W sistemin ayda 90 kWh ürettiğini, ama faturayı ayda yalnız 50 ile 80 TL düşürdüğünü yazıyor; 3 TL/kWh ile hesap 270 TL'ye yakın çıkar. Blogun 250 ay geri dönüş hesabı bu yüzden şüpheli. Aydem sayfası bu turda açılmadı.",
"Lifeverde yazısında giriş fiyatı metinde 'yaklaşık 350 €'dan', tabloda 249 € olarak geçiyor; 249 € tek modüllü 500 Wp set, 350 € genel ifade. Farklı ürün sınıfı, tam çelişki değil.",
"Türkiye'de 800 W inverterli kit fiyatı PV Balkon'da 23.880 TL (doğrulandı), Mil Enerji'de 60.588 TL (doğrulanamadı); aynı sınıf üründe iki buçuk kat fark var.",
"Elektronik-Zeit sayfası '10 Anbieter' diyor ama 7 üretici ve 4 çok markalı satıcı sayıyor; toplam 11 eder. Sayfanın kendi sayısı 10 alındı.",
"TÜİK %27 kiracı oranı hanelerin değil fertlerin oranı; önceki metin bunu hane oranı gibi okunabilecek biçimde vermişti.",
"Belge 04 fikri Mehmet Bey'in önerisi diye başlıklıyor; Belge 05 aynı işi Evde tüketici ürünü diye başlıklıyor ve öneri sahibini yazmıyor.",
"Belge 04 Almanya rakamına Mayıs 2026 tarihini veriyor; Belge 05 aynı 1,33 milyon rakamını tarihsiz yazıyor.",
"Belge 04'te İngiltere Ağustos 2026 kararı var; Belge 05 bunu düşürmüş.",
"Belge 04'te Mehmet Bey'e üç soru var, Belge 05'te iki soru; kur mu ortak mı sorusu 05'te düşmüş.",
"Etiket 6-12 ay diyor ama işin bağlı olduğu kuralın tarihi yok. Süre tahmini kuralın çıkışına bağlı; bu uyumsuzluk belgelerde açıklanmıyor.",
"Belge 04 ilk adımı EPDK ve dağıtım şirketleriyle görüşme, ilk ay işini ise enerji avukatından görüş diye yazıyor; sıra ve sorumlu belirtilmiyor."
],
"degisiklikler": [
"16 Ekim 2026 ek araştırması: 8 arama, 15 sayfa okundu; çürütücü 8 sayfa açtı, güven 4/5.",
"Lifeverde ve Elektronik-Zeit kaynak türü 'haber' ve 'rapor'dan 'diger'e çevrildi; her ikisi bağlantılı satış (affiliate) linkli ticari içerik, Elektronik-Zeit ayrıca yapay zeka destekli içerik notu taşıyor.",
"Lifeverde başlığı düzeltildi: sayfa başlığı 'Balkonkraftwerk Kaufberatung', URL eski başlığı taşıyor; ilk yayın 14 Nisan 2023, güncelleme 29 Haziran 2026 eklendi.",
"Almanya 1,32 milyon rakamı doğrulandı; Lifeverde'nin MaStR'ye atıf yaptığı ve HTW'nin kayıtsız cihaz tahmini eklendi; resmi sayfa açılmadı notu korundu.",
"Elektronik-Zeit rakamları doğrulandı (274 set, 10 satıcı, 0,51 €/Wp, %46, 250-500 €, 600-1.200 €); fiyatların Almanya %0 KDV ile olduğu notu eklendi; sayfanın 7 üretici + 4 satıcı sayarken '10 Anbieter' demesi çelişkilere yazıldı.",
"Resmî Gazete: Sayı 30772 eklendi; Madde 11/1'in 'mesken aboneleri' değil '10 kW'a kadar tip proje uygun görülen tesisler' dediği düzeltildi; başvurunun Madde 10'da olduğu, izole tesislerin Madde 5/1-b ve Madde 8'de olduğu eklendi; Madde 21 ve 26'nın araç özetinden okunduğu belirtildi.",
"EPDK 10 taslak haberi doğrulandı (4 Haziran 2026 22:40, 15 Haziran 2026 mesai bitimi, 3 ve 9 numaralı taslaklar). 'Metinlerde balkon geçmiyor' iddiası 'haber metninde ve taslak başlıklarında geçmiyor, taslak PDF'leri okunmadı' olarak daraltıldı; açık sorulara ve adımlara taslak metninin okunması eklendi.",
"TÜİK %27 kiracı oranının hane değil fert oranı olduğu ve Gelir ve Yaşam Koşulları Araştırması kaynaklı olduğu düzeltildi; %57,1 ev sahibi oranı eklendi.",
"PV Balkon fiyatları sayfada doğrulandı; liste fiyatları (39.800, 65.800, 199.800 TL), 750 W cam balkon seti 29.880 TL ve sayfada KDV ibaresi olmadığı eklendi; 'Türkiye'nin lider markası' ifadesi firma beyanı olarak işaretlendi.",
"CNBC-e damping haberi doğrulandı; altı adlı üreticiye %38,26, diğerlerine %45,99 ayrımı, soruşturma başlangıcı Mayıs 2025 ve geçici önlem Aralık 2025 eklendi; Resmî Gazete metninin açılmadığı not edildi.",
"pv magazine doğrulandı; Kuzey İrlanda hariç olduğu, %20 tüketim karşılama tahmini, UKSOL adı, 7 ürün tespitinin Byline Times gazetecisine ait olduğu, bataryaların kapsam dışı olduğu eklendi.",
"Bu turda açılmayan kaynaklara dayanan rakamlar 'doğrulanamadı' olarak işaretlendi: SolarGazete 1,34 GW ve %3,2 ile 1 Mayıs 2026 saatlik mahsuplaşma; Mil Enerji 60.588 TL; Aydem 15.000-25.000 TL ve 250 ay; PV Balkon tarife yazısı 4.000 kWh ve 3 TL/kWh; Balkonstrom 300.000 sistem ve 10 yıl garanti.",
"Lifeverde 350 € ve 249 € çelişkisi yumuşatıldı: 249 € tek modüllü 500 Wp set, farklı ürün sınıfı.",
"Tüm firma sitesi kaynakları 'firma beyanı' olarak etiketlendi.",
"Kanıt puanı 3'te bırakıldı; bant önerisi 'izle' ve kapı değerleri değiştirilmedi; bütçe notuna 'web kaynağına dayanmaz' eklendi.",
"Riskler bölümüne Almanya fiyatlarının %0 KDV ile olduğu ve Türkiye farkının bir miktar abartılı olabileceği eklendi.",
"5 Ekim 2026 tarihli inceleme dosyası verilen kaynaklar arasında yok ve dizinde bulunamadı; durum, takvim, kaynaklar ve çelişkilerdeki tüm inceleme atıfları çıkarıldı.",
"Çelişkilerden ağaç yerleşimi, Özel firmalar kolu ve EPDK etiketi maddesi çıkarıldı; kaynağı doğrulanamadı.",
"Çelişkilerden ilk ay işlerinin yapılmadığına dair inceleme kaydı maddesi çıkarıldı; durum alanında yalnızca verilen dosyalarda kayıt olmadığı yazıldı.",
"Rakamlara Belge 04 ve 05 kaynak numaraları eklendi: 04 kaynak 5, 6, 7 ve 05 kaynak 3, 4.",
"Ağustos 2026 İngiltere rakamına Belge 05'te bu bilginin olmadığı notu eklendi.",
"1,33 milyon rakamına Belge 05'in ayı yazmadığı notu eklendi.",
"800 W kural beklentisinin tek haber kaynağına dayandığı rakamlara, risklere ve kapsam notuna eklendi.",
"Risklerdeki ithal kitlere karşı sav ve teyit yanlılığı maddeleri inceleme atfı olmadan, belgelerden çıkan gözlem olarak yeniden yazıldı.",
"Adımlardaki tüm tarihlere varsayım notu ve belgedeki dayanak eklendi; 27 Ekim 2026 tarihinin bir ay sayılarak çıkarıldığı yazıldı.",
"Kapılara yatırım kapısı için varsayım notu eklendi; Belge 04 soruyu açık bırakıyor.",
"Kaynaklardaki Belge 04 bölüm listesine Harita konumları ve kaynak numaraları eklendi; Belge 05 tarihine revize notu eklendi.",
"Kapsam notundaki iki web araması ifadesi kaldırıldı; web listesindeki üç sayfanın bu doğrulamada açılmadığı yazıldı.",
"Web listesindeki üç kayıt doğrulanamadı, web araması yapılmadı; her kaydın sonuna açılmadığı notu eklendi.",
"Çelişkilere Belge 04 ve 05 başlık farkı ile Belge 05'in İngiltere kararını düşürmesi eklendi.",
"Açık sorulara kitin üretim mi ithalat mı olacağı sorusu eklendi.",
"Puan metnine etiketlerin ve haritanın kaba tahmin olduğu uyarısı eklendi."
],
