"Sıvı soğutmada teknoloji ve soğutucu sıvı patenti küresel firmalarda; MEKA'ya kalan pay sac, kaynak ve montaj olabilir, marj düşük kalabilir.",
"Küresel sıvı soğutma pazarı rakamları danışmanlık raporu; Türkiye payı bilinmiyor.",
"Gri su sistemi düşük fiyatlı, parçalı pazar; mevzuat yalnız yeni ve büyük binaları kapsıyor, önceden ruhsatlı parseller muaf, hacim sınırlı.",
