"id": "izle_bagimsiz",
"baslik": "Araç powerbank ve mobil şarj; uzun yaşam ilacı",
"bant": "izle",
"puan_metni": "05 çalışması, 27 Eylül 2026: uzun yaşam ilacı 12 iş içinde 12. sırada, etiketi izle. Bu çalışmada puan yok, yalnız sıra ve kaba etiket var: 10+ yıl, Ar-Ge çok yüksek, fonla küçük. 10 çalışması, 30 Eylül 2026: mobil şarj Bölüm 8 Ek-3'te incelendi. 10 üzerinden kapı testi bu konuya uygulanmadı; Ek-5'te test yalnız termal batarya ve lityuma yapıldı. Ek-3'ün hükmü: kanıtlanmış bir iş değil, kapı ve tarih de yok.",
"tarih": "30 Eylül 2026 ve 27 Eylül 2026",
"ne": "Bu yaprakta iki ayrı fikir var. Araç powerbank'i, EPDK tanımıyla sabit bir elektrik tesisatına bağlı olmayan şarj istasyonudur; bataryalı bir araç elektrikli otomobili yolda ya da otoparkta şarj eder. Türkiye'de üç pilot var. Uzun yaşam ilacı ise yaşlanmayı yavaşlatan ilaç geliştiren şirketlere fon üzerinden küçük pay almaktır. 05 Türkiye'de bu alanda girişim bulamadığını yazıyor; anılan şirketler yabancı.",
"neden": "Mehmet Bey'in ölçütü MEKA'dan bağımsız, teknolojik, yüksek getirili ve ilk giren kazanır türünden iş. 10 çalışması mobil şarjı 29 Eylül tarihli sorulara cevap olarak Ek'te ele aldı. Uzun yaşam ilacı 05'in haritasında potansiyeli büyük görülen tek sağlık kalemi. İki çalışma da bu iki konuda MEKA katkısı yazmıyor; bu yüzden kişisel yatırım ya da izleme listesi konusu.",
"rakamlar": [
{
"deger": "48.649 şarj noktası, ayda 3.527.070 işlem, 97.469 MWh",
"aciklama": "EPDK Ağustos 2026 verisi; haber Yeşil Haber, 20 Eylül 2026. İşlem başına ortalama 27,63 kWh. Nokta başına günde yaklaşık 2,3 işlem ve yaklaşık 65 kWh düşüyor; bu 10 yazarının kendi hesabı ve ağ ortalaması, otoyol ile şehir içi noktaları ayırmıyor.",
"kaynak": "10, Ek-3, Pazar"
},
{
"deger": "216 TL, yaklaşık 4,4 $",
"aciklama": "Mobil şarjda ziyaret başına kaba gelir; 18 kWh çarpı 12 TL/kWh. 12 TL/kWh Trugo sitesinde seçili sabit istasyonlar için kampanya fiyatı, mobil hizmetin fiyatı değil. Günde 8 ile 10 ziyaret varsayımıyla 1.700 ile 2.200 TL, yani 35 ile 44 $. Elektrik, sürücü, araç, batarya, sigorta ve lisans bunun dışında; bu kalemler için kaynak yok.",
"kaynak": "10, Ek-3, Kaba ekonomi"
},
{
"deger": "1.914.200 TL",
"aciklama": "Şarj ağı işletmeciliği lisans bedeli, 2026. Yaklaşık 39 bin $, 10 yazarının hesabı. Haber mobil için ayrı bedel yazmıyor.",
"kaynak": "10, Ek-3, Kurallar"
},
{
"deger": "3 pilot, gelir verisi yok",
"aciklama": "Trugo ve EVbee 2 Eylül 2024'te ilk etapta 6 ünite, bir yılda 20 ünite hedefi; OtoPriz 29 Ocak 2025, İstanbul, 31 Mart 2025'e kadar ücretsiz; ABB ve Yüce Auto-Škoda 18 Mayıs 2026. Hiçbirinde gelir, filo ya da finansman verisi yok.",
"kaynak": "10, Ek-3, oyuncu tablosu"
},
{
"deger": "18,4 milyar $",
"aciklama": "2025'te uzun yaşam alanına yapılan yatırım; ilk onay yaklaşık 10 yıl içinde bekleniyor. Kaynak 28'in bağlantı başlığı 30 milyar $ üstü ve 2035 diyor; 05 metniyle başlık uyuşmuyor, teyit gerekiyor.",
"kaynak": "05, madde 12, kaynak 28"
},
{
"deger": "435 M$ ve 1,8 milyar $",
"aciklama": "NewLimit Haziran 2026'da 435 M$ aldı, değeri yaklaşık 3,1 milyar $. Retro 1,8 milyar $ değerlemeyle tur kapattı. İnsanda onaylı ilaç yok; en yakını Loyal'ın köpek ilacı, FDA etkinlik ve güvenlik bölümlerini kabul etti.",
"kaynak": "05, madde 12, kaynak 29, 30 ve 31"
}
],
"durum": "Mobil şarj 30 Eylül 2026 tarihli 10 numaralı çalışmanın Ek-3 bölümünde incelendi. Hüküm açık: kanıtlanmış bir iş değil, kapı ve tarih de yok. Yurt dışında FreeWire 2024'te faaliyeti bıraktı, Moxion Ağustos 2024'te iflas başvurusu yaptı; ayakta kalan SparkCharge kurumsal hizmete kaymış görünüyor. Uzun yaşam ilacı 27 Eylül 2026 tarihli 05 çalışmasında 12. sırada ve izle etiketli; Türkiye'de girişim bulunamadı. Çalışmalarda iki konu için görüşme, teklif ya da karar yok. Ön bant izle korunuyor; elendi değil, çünkü 05'in şimdilik değil listesinde yalnız güneşli katlanır ev, güneş kiremidi ve barutu doğrudan yakıt yapmak var, 10 ise Ek konularını elemiyor.",
"acik_sorular": [
"Mobil şarj hizmetinde çağrı primi alınabilir mi; 10 yazarı bilmediğini ve yönetmelik metninin hukukçu okuması gerektiğini yazıyor.",
"Mobil şarjın maliyet kalemleri bilinmiyor: elektrik, sürücü, araç, batarya, sigorta ve lisans için kaynak yok. 10 Bölüm 9 bunu bilinmeyenler arasında sayıyor.",
"Uzun yaşam ilacına hangi fon üzerinden girilecek; 05'te fon adı ve bilet büyüklüğü yok.",
"Uzun yaşam yatırım rakamı 18,4 milyar $ mı, 30 milyar $ üstü mü; 05 metni ile kaynak 28'in başlığı uyuşmuyor.",
"Yatırım kişisel mi MEKA üzerinden mi; 04 ve 05 bu soruyu Mehmet Bey'e soruyor, yanıt çalışmalarda yok."
],
