"kapi_etkisi": {
"sirket": "Çalışmaların tamamına yakını MEKA şirketi için yazılmış; sirket seçilince sıralama bu sayfadaki gibi kalır: tahkimat prekast hattı, tahkimat kalıbı, flat rack ve mühimmat hattı ekipmanı önde, arkasından lançer ve fırlatma üssü, konteyner ve şelter, enkaz agregası ve belediyeler. Yatırım kapısındaki sirket etiketi dokuz savunma yaprağında, mineral, enkaz, belediye ve Beylikova'da varsayımdır; raporlar kişisel seçeneği hiç ele almamış.",
"kisisel": "Kişisel yatırımla anlamlı kalan yapraklar yalnız ikisi etiketliler: Milvus azınlık payı, çimento katkısında ruhsat ya da kül hakkı, tungsten junior hissesi, nükleerde yabancı atölye payı ve termal bataryada yerli firmaya yatırım; termalin tek adayı olan EEN profili 1 Ekim 2026'da kapandı. Dört savunma kolu, konteyner ve şelter, lançer ve mevcut ürünle satış yaprakları olan enkaz, belediyeler, RES temeli ve Beylikova kişisel yatırımla yürümez. Kisisel seçilirse öne çıkan bant boşalır; listenin başına Milvus ile çimento ruhsat haritası geçer.",
"dusuk_butce": "1 ve 2 dilimi bu dalın doğal dilimi: dört savunma kolunun ilk dilimi 1 ya da 2 (prekast 1, kalıp 1, mühimmat 1, flat rack 2); lançer, konteyner ve şelter, istihkam, termal, çimento, nükleer, trafo, parçalayıcı ve Milvus 2; mineral, enkaz, belediyeler, Beylikova, RES temeli, vinç, uçak bakım ve izleme kalemleri 1. Düşük bütçede sıralama değişmez; yalnız tungsten (dilim 4), üretilmiş kum (3), asfalt plenti (3) ve elenenler (3) listeden düşer. Termal batarya pilotu (6. ay kapısında 1,5 ile 2 M$) ve nükleer atölye alımı da bu dilimde kapalı kalır.",
"yuksek_butce": "3 ve 4 dilimi seçilirse tungsten (junior yerleştirmesi 10 ile 50 milyon Avustralya doları, işleyici 100 ile 450 milyon dolar), nükleer atölye alımı, çimento kalsine kil ünitesi (20 ile 80 milyon dolar), termal pilot (1,5 ile 2 M$) ve üretilmiş kum tesisi (3 ile 15 M$) açılır. Savunma kolları yüksek bütçeye ihtiyaç duymadığı için sıralamanın tepesi değişmez; yüksek bütçe asıl ikincil bandın alt yarısındaki tungsten ve nükleeri öne çeker. Kum ve asfalt izle bandında kalır, çünkü engel para değil ocak ortağı ve kalabalık pazar.",
"kur": "Kur seçilince yol etiketi kur olan yapraklar öne çıkar: tahkimat prekast hattı, tahkimat kalıbı, belediyeler ve mobil parçalayıcı; ikisi etiketli flat rack, mühimmat hattı, lançer ve fırlatma üssü, mineral, enkaz, Beylikova ve RES temeli de kendi üretim ayağıyla listede kalır. Yol etiketi ortak olan konteyner ve şelter, vinç alt yükleniciliği, termal batarya, Milvus, üretilmiş kum, asfalt plenti ve elenenler geriye düşer. İlk iki sıra değişmez.",
"ortak": "Ortak seçilince alt yüklenicilik ve pay alma yaprakları öne çıkar: konteyner ve şelter gövdesi, vinç üreticilerine alt yüklenicilik, termal batarya EPC ve imalat ortaklığı, Milvus, üretilmiş kum JV; ikisi etiketlilerden flat rack (kanal ortak), mühimmat hattı (Repkon ve STV alt yükleniciliği), lançer (Roketsan, ASELSAN, Koluman), nükleer JV ve tungsten junior hissesi. Tahkimat prekast hattı ve kalıbı kur yolunda, ama rapor yerli tercih riskine karşı yerel prekastçı ve ortakla çalışmayı öneriyor; bir basamak gerileyebilir, bantta kalır. Belediyeler ve mobil parçalayıcı geri düşer."
},
"uyarilar": [
"Puan ölçekleri birbirine eklenemez: savunma raporu 5 üzerinden yedi kriterli ağırlıklı puan verir; 5+5 çalışması 10 üzerinden kapı yapısını ölçer ve MEKA uyumunu, getiriyi puana katmaz; 03 ve 05 yalnız sıra ve kaba etiket verir. 03 savunmayı on alanda 6. sıraya koyup mineral zenginleştirmeyi 1. yapar; bu sayfa savunma raporunu daha iyi kanıtlı sayıp dört savunma kolunu öne aldı.",
"Bu dalın 25 yaprağının hiçbirinde 22 Eylül 2026'dan sonra atılmış adım kaydı yok. Tesis veri formu doldurulmadı ve dokuz savunma yaprağının teknik uyum puanı varsayım; MSB sınıflandırma görüşü istenmedi; 30 Eylül 2026 YETEN ve SSB fuar desteği tarihi geçti; savunma raporu kendi doğrulamasının yarısını tamamlayamadı, kontrol edilen 38 iddianın 13'ü düzeltildi.",
"Ağaçtaki yer tartışmalı. Savunma yapraklarında fatura kesilen taraf özel, kapılar ve nihai talep kamu; Tablo 7.3 prekast hattını ve kalıbı savunma alıcılı saymıyor, yönetim savunmayı dar tanımlarsa ilk iki sıra bu listeden düşer. Termal, çimento, nükleer ve tungsten MEKA'dan bağımsız taramalardan geliyor; MEKA dalına konması yorum.",
"Zayıf kanıt örnekleri: RES temeli ve Beylikova'nın kilit rakamları webden, çalışmalarda yok; mobil parçalayıcı kanıt 1; Milvus'un yatırım turu iki belgede farklı (4,5 M$ Seri B, Mayıs 2025 ile 5,5 M$ Seri A, Temmuz 2025); termal bataryada Magaldi'nin 22 ile 24 Ekim 2026 ANKIROS katılımı doğrulanmadı ve EEN profili kapandı; tungsten fiyatları Haziran 2026 tarihli.",
"Eşik ile bant tam örtüşmüyor: konteyner ve şelter 3,70 ile ikincil sınıfta ama rapor dört kola almış; fırlatma üssü aynı 3,70 ile 0 ile 12 ay hızlı kazanım; vinç alt yükleniciliği 3,35 ile ikincil eşiği 3,40'ın altında ama ikincil bandı aldı. Lançer yaprağı iki farklı ufku, 0 ile 12 ay ve 18 ile 36 ay, tek bantta tutuyor. Rakam çelişkileri de var: Baltık bunker sayısı 600 ile 1.600, kanca yükleyici 4.000 ile 4.000'e kadar."
],
