"adim": "Yalnız yüksek bütçe seçilirse: ABD ve AB'de satılık ya da ortak arayan izinli tehlikeli atık işletmelerini listele; izin devri, CFIUS ve AB yabancı yatırım denetimi için hukuk görüşü al.",
"kim": "Mehmet Bey'in görevlendireceği danışman ve dış hukuk bürosu",
"ne_zaman": "Bütçe kararından sonra, 30 Kasım 2026'ya kadar",
"konu_id": "pfas"
