"kapi_etkisi": {
"sirket": "MEKA üzerinden seçilirse SSB batarya ekosistemi ve OTAĞ ile enerji verimliliği üçlüsü (su geri kazanımı, sıvı soğutma, ısı pompası) öne çıkar; bu ikisi yalnız şirket kanalında çalışıyor. ODTÜ Teknokent, Novator, Pyramp, PFAS, balkon GES, jeotermal, Avrupa depolama ve lityum iki yolda da açık kalır, ama her yatırım KAP'a bildirilir ve melek teşviki kullanılamaz. Biyolojik ilaç, ağır nadir toprak ve araç powerbank ile uzun yaşam yaprakları kişisel varsayımıyla yazıldığı için geriye düşer.",
"kisisel": "Kişisel seçilirse biyolojik ilaç ikamesi, ağır nadir toprak ve araç powerbank ile uzun yaşam ilacı öne gelir; melek yatırımcı teşviki ODTÜ Teknokent kısa listesi ve Novator'u güçlendirir, ama indirim tavanı yıllık 2,5 milyon TL, hisse en az 2 yıl tutulur ve teşvik 31 Aralık 2027'de biter. SSB batarya ve enerji verimliliği üçlüsü düşer; Pyramp'ta teşvikin yabancı hissede geçerliliği belirsiz. PFAS ve nadir toprak biletleri kişisel servetle karşılanacaksa 10 milyon dolar üstü dilim gerekir.",
"dusuk_butce": "1 ve 2 dilimi seçilirse sıra şöyle daralır: ODTÜ Teknokent giriş yolları, Novator, balkon GES kiti, Pyramp'ın ilk teması, jeotermal ruhsat (saha başına 20 ile 41 bin dolar muhammen), OTAĞ katılımı ve bina su geri kazanımı. PFAS (emsal 305 milyon dolar) ve ağır nadir toprak (yüzlerce milyon dolar) listeden çıkar; Avrupa depolama hakları, biyolojik ilaç ve lityum da 3. dilim varsayımıyla kapanır.",
"yuksek_butce": "3 ve 4 dilimi seçilirse PFAS imha kapasitesi ve ağır nadir toprak dalın başına geçer; ikisi de tarihli penceresi ve emsal işlemi olan yurt dışı varlık alımları. Avrupa depolama hakları (İtalya emsali 37.500 avro/MW), biyolojik ilaç (lisans ya da listeli şirket alımı) ve lityum (emsal Solinved hattı yaklaşık 5 milyon dolar) açılır. Küçük biletli yapraklar yine yapılabilir, ama yönetim dikkati yurt dışı hak alımına kayar ve MEKA bilançosu çalışmalarda yok.",
"kur": "Kur seçilirse dal çok daralır: yalnız balkon GES kiti doğrudan kur yolunda; enerji verimliliği üçlüsünün su geri kazanımı ve sıvı soğutma ayağı, jeotermal ihaleye doğrudan girmek ve lityumda fabrika pilotu (Belge 04 yolu) kur olarak okunabilir. ODTÜ Teknokent, Novator, Pyramp, PFAS, nadir toprak, Avrupa depolama, biyolojik ilaç, SSB batarya ve araç powerbank ile uzun yaşam yaprakları pay alma ya da satın alma yolu olduğu için düşer.",
"ortak": "Ortak seçilirse dalın büyük kısmı açık kalır: ODTÜ Teknokent giriş yolları, Novator ve Pyramp (yüzde 25 altı azınlık pay), PFAS, nadir toprak ve Avrupa depolama (varlık ya da hak alımı), biyolojik ilaç (lisans ya da şirket alımı), SSB batarya (offset, Sanayileşme, OTAĞ) ve uzun yaşam ilacı (fon payı). Jeotermalde ruhsatlı şirket alımı, lityumda Pomega ve Kontrolmatik varlıkları ortak yoluna girer. Balkon GES kiti düşer; enerji verimliliğinde yalnız ısı pompası için yabancı lisans ya da ortaklık kalır."
},
"uyarilar": [
"Görüşme kaydı yok. 15 Ekim 2026 itibarıyla 14 yaprağın hiçbirinde şirket, fon ya da idareyle temas kaydı yok; Belge 04'ün 27 Ekim 2026 hedefli ilk ay planı yapılmış görünmüyor. Novator'da aynı gün tarihli iki belge çelişiyor: Belge 04 görüşmeden yatırım önermiyor, Belge 05 ilk ortak biz oluruz diyor.",
"Puanlar farklı ölçeklerde ve kendi içinde tartışmalı. Belge 04 ve 05 sıra numarası verir (7 ve 12 iş), Belge 10 10 üzerinden kapı testi puanı verir; bunlar toplanamaz. Lityum Belge 05'te 3. sırada ama Belge 10'da 2/10 ve test edilen iş birebir aynı değil; PFAS 8/10 ama yazar Takvim puanı 1 olursa 7 olur diyor; biyolojik ilaçta cetvele göre toplam 5 çıkarken 6 verilmiş.",
"Bilet ve bilanço boşluğu. PFAS'ta tek bilet işareti 305 milyon dolar, nadir toprakta yüzlerce milyon dolar; MEKA'nın nakdi ve bilançosu çalışmalarda yok. Belge 04 ve 05 üç bütçe dilimi sorar, bu kapı şeması dört dilim kullanır; yaprakların dilim eşleştirmesi varsayım.",
"Bağımsız ölçütü ile metin tutarsız. Novator ve Pyramp için Belge 05 MEKA katkısı yazar (pano, konteyner, gövde, soğutma) ve stratejinin 2. adımı üretimi MEKA'ya alır; enerji verimliliği üçlüsü ve SSB batarya ise imalat ya da tedarikçi işi. Dalın adı ile içeriğinin bir kısmı örtüşmüyor; yerleştirme yönetimin kararı.",
"Eskiyen tarihler ve doğrulanmamış kaynaklar. Erzurum jeotermal ihalesi 13 Ekim 2026'da geçti, sonucu yok; OTAĞ'ın Mayıs 2026 bitişi geçti, raporu yok; melek teşviki 31 Aralık 2027'de biter ve yabancı hissede (Pyramp) geçerliliği ele alınmadı. 5 Ekim 2026 inceleme dosyası ile 07 ve 08 bu turda verilmedi; Pyramp, balkon GES ve enerji verimliliğindeki 15 Ekim 2026 web bulguları yeniden doğrulanmadı; depolama ön lisans rakamı belgelerde üç farklı değer (25,6 GW, 38 GW, 28,6 ve 33,1 GW)."
],
