"kapi_etkisi": {
"sirket": "Yirmi bir yaprağın on sekizi zaten şirket üzerinden yazılmış; şirket seçilirse sıralama değişmez, tahkimat prekast hattı, tahkimat kalıbı, flat rack ve mühimmat hattı ekipmanı önde kalır, arkalarından konteyner ve şelter gövdesi ile enkazdan agrega gelir. Çimento katkısı, nükleer imalat ve tungstende yalnız makine ve tesis payı şirkete kalır, ruhsat ve hisse tarafı düşer. Not: hiçbir çalışma kişisel yatırımı ele almadığı için şirket seçimi çoğu yaprakta derleyen varsayımı.",
"kisisel": "Hiçbir yaprak yalnız kişisel yatırım için yazılmamış; kişisel seçilirse üretimi MEKA tesisine bağlı dört savunma kolu ile konteyner, vinç, istihkam, enkazdan agrega, mineral zenginleştirme, RES temeli, üretilmiş kum ve mobil parçalayıcı düşer. Geriye tungsten junior hissesi, çimento katkısında ruhsat ya da kül hakkı, nükleerde yabancı atölyede azınlık payı ve termal bataryada yerli firmaya yatırım kalır; bu dördünün kişisel yolu da varsayım ve en yüksek kanıtlısı termal, 4. Kişisel seçim bu bölgeyi fiilen boşaltır; ağacın MEKA'dan bağımsız dalına bakmak gerekir.",
"dusuk_butce": "İlk dilim (100 bin dolar altı) ve ikinci dilim (100 bin ile 1 milyon dolar) seçilirse öne çıkan dört yaprağın tamamı kalır: prekast hattı, kalıp ve mühimmat hattı 1. dilimde, flat rack 2. dilimde; konteyner ve şelter, istihkam, termal batarya, çimento katkısı, nükleer imalat, trafo ve mobil parçalayıcı da 2. dilime sığar. Düşen yapraklar tungsten (4. dilim), üretilmiş kum (3), asfalt plenti (3) ve bilgi amaçlı elenenler (3). Dikkat: dilimler ilk adım için; flat rack'te seri üretim için robotik kaynak hücresi ve termalde 1,5 ile 2 milyon dolarlık pilot 3. dilime taşar.",
"yuksek_butce": "3. ve 4. dilim seçilirse bu dilimi gerçekten isteyen tek yaprak tungsten; üretilmiş kum ve asfalt plenti de 3. dilime girer ama ikisi de izle bandında ve çalışmalar ikisine de koşullu çıkış kuralı koyuyor. Yüksek bütçe asıl olarak öne çıkan ve ikincil kolların ikinci aşamasını açar: flat rack'te robotik kaynak hücresi ve seri üretim (karar Mart 2027), tahkimatta mobil fabrika, termalde pilot, nükleerde sertifikalı atölye alımı, çimento katkısında 20 ile 80 milyon dolarlık kalsine kil ünitesi. Bu ikinci aşamaların hiçbirinin tutarı çalışmalarda kaynaklı değil.",
"kur": "Kendin kur seçilirse tahkimat prekast hattı ve tahkimat kalıbı en güçlü konumda: rapor ikisini MEKA'nın kendi üretimi ve ihracatı olarak yazıyor, ortak yalnız yerli tercih riskine karşı azaltma önlemi. Flat rack ve mühimmat hattı üretim tarafı kur, satış kanalı ortak olduğu için kalır; mobil parçalayıcı da kur ama kanıt 1. Konteyner ve şelter, vinç alt yükleniciliği, termal batarya, üretilmiş kum ve asfalt plenti yalnız ortak yoluyla yazılmış, kur seçilirse düşer.",
"ortak": "Ortak seçilirse konteyner ve şelter gövdesi (Avrupa ana yüklenicileri, Dorçe, Nurol İnşaat, STM), vinç üreticilerine alt yüklenicilik (Liebherr, Palfinger, Hiab, Koluman) ve termal batarya (Magaldi ve Rondo tipi EPC ve imalat ortaklığı) öne çıkar; flat rack OEM alt yükleniciliği ve mühimmat hattında Repkon ile STV kanalı zaten ortak yolu. Prekast hattı ve kalıp zayıflar çünkü rapor ortağı ana yol değil azaltma önlemi sayıyor; üretilmiş kum ve asfalt plenti ortak çıkarsa izle bandından yukarı çıkabilir. Elenenlerin yerine önerilen kolların hepsi de alt yüklenicilik; bu kapı o kolları besler."
},
"uyarilar": [
"Savunma raporundaki tüm teknik uyum puanları tesis verisi gelmeden varsayım; rapor doğrulamanın yaklaşık yarısını tamamlayamadı ve kontrol ettiği 38 iddianın 13'ünü düzeltti. Tablo 8.1.2 tahkimat için teknik uyumu 4 verip kalıp ve kür bilgisinin eksik olduğunu yazarken Tablo 7.1 kalıp nişine 5 veriyor; 4,35 ve 4,25 puanlar bu yüzden iyimser olabilir. 22 Ekim 2026 ve 21 Aralık 2026 tarihleri raporda yazılı değil, 22 Eylül 2026 artı bir ay ve artı 90 gün hesabı.",
"Bölgenin ağaçtaki yeri tartışmalı: dört savunma kolunda fatura kesilen taraf özel firma ama kayıt kapıları (YETEN, SSB, NCAGE, NSPA, MSB) ve nihai talep kamu; Tablo 7.3 savunmayı dar tanımlayınca prekast hattı ve kalıp listeden düşüyor, 03 belgesi ise savunmayı on alanda 6. sıraya koyup 6 ile 24 ay yazıyor. Kartın 30 günlük ödeme vadesi avantajı da yalnız kamuya doğrudan satışta geçerli; Hiab, Rheinmetall gibi özel OEM'lerde vade 50 ile 109 gün.",
"Bölgede dört ayrı puan ölçeği var ve toplanamaz: savunma raporu 5 üzerinden yedi kriter, 5+5 taraması 10 üzerinden yalnız kapı yapısı (MEKA uyumu ve getiri ölçülmüyor), 03 ve 05 belgeleri yalnız sıra ve kaba etiket. 5+5 puanlarında tutarsızlık da var: trafoda kapı yok denip Kapı kutusuna 1 puan verilmiş, tungsten ve üretilmiş kumda Boşluk 2 puanı yazarın doğrulanmamış çıkarımı; 09 özetleri MEKA makine payını 10 uzun çalışmasından daha yüksek gösteriyor.",
"Termal bataryada kaynaklar birbirini tutmuyor: 05 belgesi 1. sıra, 10 belgesi 3 / 10 ve testi geçmedi; Magaldi'nin 22 ile 24 Ekim 2026 ANKIROS katılımı 10 belgesinde doğrulanamadı, EEN profili 1 Ekim 2026'da kapandı, 07 dipnotu avro ile doları eşit almış. Enkazda da 03 Ar-Ge yok derken GPT kartı hazır ekipman, hazır proses değil diyor; 570 bin ton rakamı 03'te hem Beylikova cevheri hem Suriye enkazı için geçiyor.",
"Kanıt 1 ve 2 olan dört yaprak (mobil parçalayıcı, RES temel paketi, asfalt plenti, izleme kalemleri) tek belgede tek paragrafa dayanıyor; bu yapraklardaki web kaynaklı bilgiler (YEKA 7 saha ve 36 ay kurulum, Polygonmach, 419 kr/kWh koşulları, Alt Carbon'un kırma tesisi almaması) bu turda doğrulanmadı. Kişisel yatırım seçeneği hiçbir çalışmada ele alınmadığı için 21 yaprağın yatırım kapısı ve bütçe dilimi büyük ölçüde derleyen varsayımı."
],
