"ozet": "Bu bölgede üç yaprak var ve üçü de ikincil bantta: Lançer ve fırlatma altyapısı, Belediye hafriyat tesisleri ve EKAP ihaleleri, Beylikova nadir toprak tesisi. Alıcılar devlet kurumları ve kamu ağırlıklı ana yükleniciler: Roketsan, ASELSAN, Türkiye Uzay Ajansı, belediyeler ve Eti Maden. En güçlü kanıt Lançer yaprağında; savunma raporu talebi sayılarla doğruluyor, kanıt 4 ve güven 5. Gelire en yakın işler Belediye ile Lançer'in fırlatma üssü parçası; ikisi de bugünkü ürünle satılır. Ortak engel şu: hiçbir yaprakta ihale takvimi, ana yüklenici ya da muhatap adı yok ve Eylül 2026 için verilen iç görevler kapanmadı.",
