"kapi_etkisi": {
"sirket": "Üç yaprak da şirket yatırımı ister; şirket seçilirse sıralama olduğu gibi kalır: Lançer, Belediye, Beylikova. Savunma raporu doğrudan MEKA şirketi için yazılmış; Belediye ve Beylikova da MEKA referansı ve MEKA üretim hattıyla girilen işler.",
"kisisel": "Kişisel yatırım seçilirse bu bölgede öne çıkan yaprak kalmaz. Lançer raporu kişisel seçeneği hiç ele almıyor; Belediye ve Beylikova şirket ihalesi ve şirket üretimi ister. Bölge bu kapıda izle konumuna düşer.",
"dusuk_butce": "1 ve 2 dilimi üç yaprağı da kapsar; sıralama değişmez. Belediye ve Beylikova 1. dilimde kalır, ilk para EKAP izleme, teklif dosyası ve temas için, varsayım olarak 100 bin dolar altı. Lançer 2. dilimde: fırlatma üssü satışı yeni yatırım istemez, lançer tarafı için TGB fiziki güvenlik 1 ile 3 milyon TL, AQAP ve EYDEP 10 ile 25 bin avro, MIL-STD testleri 20 ile 80 bin avro.",
"yuksek_butce": "3 ve 4 dilimi bu bölgede hiçbir yaprağın koşulu değil; daha fazla para sıralamayı değiştirmez. Fazla kaynak ancak Beylikova'da listede olmayan öğütme, flotasyon ve manyetik ayırma kısmını kapatmaya ya da Lançer'de 18 ile 36 aylık gövde ve üst yapı opsiyonunu öne çekmeye gidebilir; bu bağlantı kaynaklarda yok, varsayım.",
"kur": "Kendi başına kur seçilirse Belediye öne geçer: tek yolu kur, MEKA kendi makinesini üretir ve EKAP'a doğrudan teklif verir. Lançer'in fırlatma üssü parçası da kalır, MEKA beton santralini ve çelik yapıyı kendisi satar; gövde ve üst yapı parçası alt yüklenicilik olduğu için geriler. Beylikova'da yalnız kırma, eleme ve konveyör paketi kalır; tesise giriş yine Eti Maden ihalesine bağlı.",
"ortak": "Ortak seçilirse Lançer ve Beylikova öne çıkar. Lançer gövdesi ve üst yapıları Roketsan, ASELSAN ve Koluman altında alt yükleniciliktir; Beylikova'da öğütme ve flotasyon için yerli ya da yabancı ortak gerekir, 02 Madensan ve Aksa Magnet'i anıyor. Belediye geriler; kaynaklarda bu iş için ortaklık önerisi yok."
},
"uyarilar": [
"Beylikova: 03 belgesi 24 Eylül 2026'da bu alanı 1. sıraya koyuyor ama kanıt tek cümle; 02 kartı bir gün önce metalik cevheri uzak ihtimal saymış, 10 çalışması Beylikova'yı kaynak listesine almamış. Pilot tesisin yüzde 90 zenginleştirmesi, 1 Mayıs 2026 temel atma hedefi ve 31 Ağustos 2026 kamulaştırma kararı webden; bu kontrolde doğrulanmadı. 570 bin ton rakamı 03'te hem Beylikova cevheri hem Suriye enkazı için geçiyor ve tarihi yazılmamış.",
"Belediye: 03 işi 0 ile 6 ay ve Ar-Ge yok sayıyor; GPT kartı aynı işi 12 ile 24 ay sayıyor ve karma moloz için ek ayırma ve test istiyor. Kanıt tek belediye ve tek ihale; Giresun ihalesinin yeterlik tarihi 22 Eylül 2026 web ilanından, bu turda yeniden doğrulanmadı ve pencere kapandı. Pazar büyüklüğü, yıllık ihale sayısı ve rakip bilgisi çalışmalarda yok.",
"Lançer: yaprak iki farklı ufku tek bant altında topluyor; fırlatma üssü satışı 0 ile 12 ay, gövde ve üst yapı 18 ile 36 ay. Eski füze rampası referansı belgesiz, yalnız yönetimin hatırası; rapor da kamuya açık kaynakta bulamadı. Lançer çelik yapısı ML4 sınıfında, ihracat yalnız Roketsan ve ASELSAN paketleri üzerinden dolaylı. Rapor kendi doğrulamasının yaklaşık yarısını tamamlayamadığını yazıyor; Hidrokon örneği Roketsan teyidi olmayan 2016 duyurusuna dayanıyor.",
"Bölge geneli: üç yaprakta da karşı taraf belirsiz. Beylikova'da ihale takvimi ve ana yüklenici, Somali üssünde yüklenici, HİSAR ve SİPER'de üst yapı üreticisi, belediyelerde geçmiş satış listesi yok. Eylül 2026 için verilen iç görevler, belediye satışlarını sormak, Metso kapsamını okumak ve arşiv taraması, süresi geçmiş ve sonucu dosyalarda yok.",
"Puanlar farklı ölçekte: 03 yalnız sıra numarası veriyor, 10 çalışması 10 üzerinden kapı yapısını ölçüyor ve MEKA uyumunu ölçmüyor, savunma raporu 5 üzerinden puanlıyor. Bu sayfadaki sıralama bu puanları toplamadı; bant, kanıt gücü ve gelire yakınlıkla kuruldu. Lançer sıra numaraları Tablo 7.1 metninden alındı, eşit puanlı nişler yüzünden bir basamak kayabilir."
],
